(function () {
  const o = LESSONS.js, N = {"cond": {"t": "Умови та оператори", "p": ["Умови дозволяють програмі приймати рішення. Порівняння дають булеве значення: <code>===</code> (дорівнює), <code>!==</code>, <code>&lt;</code>, <code>&gt;</code>, <code>&lt;=</code>, <code>&gt;=</code>. Умови комбінують логічними операторами <code>&amp;&amp;</code> (і), <code>||</code> (або), <code>!</code> (не).", "У умовах JavaScript будь-яке значення перетворюється на true або false. Хибними (falsy) є лише <code>false</code>, <code>0</code>, <code>\"\"</code>, <code>null</code>, <code>undefined</code> і <code>NaN</code>. Усе інше вважається істинним."], "code": ["const age = 17;\n\nif (age >= 18) {\n  console.log(\"Повнолітній\");\n} else if (age >= 14) {\n  console.log(\"Підліток\");\n} else {\n  console.log(\"Дитина\");\n}\n\nconst label = age >= 18 ? \"adult\" : \"minor\";\nconsole.log(label);\n\nconst day = 3;\nswitch (day) {\n  case 1: console.log(\"Понеділок\"); break;\n  case 2: console.log(\"Вівторок\"); break;\n  case 3: console.log(\"Середа\"); break;\n  default: console.log(\"Інший день\");\n}", "const user = { name: \"Олена\", address: null };\n\nconsole.log(user.address?.city);        // undefined, без помилки\nconsole.log(user.nickname ?? \"гість\");  // гість\nconsole.log(user.name && user.name.length);\n\nif (!user.name) {\n  console.log(\"Імені немає\");\n}"], "note": "Оператор <code>?.</code> зупиняє читання, якщо проміжне значення null або undefined, а <code>??</code> підставляє запасне значення лише для null і undefined (на відміну від <code>||</code>, який реагує і на 0).", "work": "У реальному коді дані часто приходять із сервера в неповному вигляді, тому <code>?.</code> і <code>??</code> зустрічаються постійно. Також прийнято спершу відсіювати некоректні випадки й виходити з функції раніше (так звані guard clauses), замість глибоких вкладених if.", "tasks": ["Напишіть програму, що за балом 0–100 виводить оцінку: A, B, C або F.", "Отримайте місто з об'єкта <code>{ address: { city: \"Київ\" } }</code> безпечно, навіть якщо address відсутній."]}, "loops": {"t": "Цикли", "p": ["Цикл повторює блок коду. Класичний <code>for</code> має три частини: початок, умову продовження та крок. Цикл <code>while</code> працює, поки умова істинна, а <code>do...while</code> виконується щонайменше раз.", "Інструкція <code>break</code> негайно виходить із циклу, а <code>continue</code> пропускає поточну ітерацію й переходить до наступної. Для перебору значень масиву зручний <code>for...of</code>."], "code": ["for (let i = 1; i <= 5; i++) {\n  console.log(\"Ітерація\", i);\n}\n\nlet n = 10;\nwhile (n > 0) {\n  n -= 3;\n}\nconsole.log(n);\n\nconst nums = [4, 9, 12, 7];\nfor (const x of nums) {\n  if (x % 2 === 1) continue;\n  console.log(\"Парне:\", x);\n}", "const prices = [120, 80, 300, 45];\nlet total = 0;\nlet firstExpensive = null;\n\nfor (const p of prices) {\n  total += p;\n  if (firstExpensive === null && p > 250) {\n    firstExpensive = p;\n  }\n}\nconsole.log(\"Разом:\", total, \"Перше дороге:\", firstExpensive);"], "note": "Цикл, умова якого ніколи не стане хибною, зависає вкладку браузера. Завжди перевіряйте, що змінна в умові змінюється.", "work": "У проєктах прості цикли <code>for</code> трапляються рідше, ніж методи масивів, але без них не обійтися, коли потрібен ранній вихід через <code>break</code> або складний крок. Для масивів за замовчуванням використовують <code>for...of</code>, а не індекси.", "tasks": ["Виведіть усі числа від 1 до 100, кратні 7.", "Знайдіть перше число в масиві, більше за 50, і зупиніть цикл через break."]}, "strings": {"t": "Рядки та числа", "p": ["Рядки мають багато корисних методів: <code>slice</code> бере частину, <code>includes</code> перевіряє наявність підрядка, <code>split</code> розбиває на масив, <code>trim</code> прибирає зайві пробіли, <code>toUpperCase</code> змінює регістр. Рядки незмінні, кожен метод повертає новий.", "Шаблонні рядки у зворотних лапках дозволяють вставляти значення через <code>${…}</code> і писати текст у кілька рядків. Для чисел важливі <code>Number()</code>, <code>parseInt</code>, <code>toFixed</code> та об'єкт <code>Math</code>."], "code": ["const title = \"  JavaScript для роботи  \";\nconsole.log(title.trim().toUpperCase());\nconsole.log(title.includes(\"робот\"));\nconsole.log(\"a,b,c\".split(\",\"));\nconsole.log(\"Привіт\".slice(0, 3));\n\nconst name = \"Олена\";\nconst total = 1234.5;\nconsole.log(`Клієнт: ${name}, сума: ${total.toFixed(2)} грн`);", "console.log(Number(\"42\"), Number(\"abc\"));\nconsole.log(parseInt(\"15px\"), parseFloat(\"3.14\"));\nconsole.log(Math.round(4.6), Math.floor(4.9), Math.max(3, 8, 1));\nconsole.log(0.1 + 0.2);                     // 0.30000000000000004\nconsole.log(Math.round((0.1 + 0.2) * 100) / 100);\nconsole.log(Number.isNaN(Number(\"abc\")));"], "note": "Дробові числа зберігаються з похибкою: <code>0.1 + 0.2</code> не дорівнює 0.3. Для грошей працюють із копійками як із цілими числами.", "work": "Користувацький ввід завжди приходить рядком, тому перетворення та перевірка чисел (<code>Number</code>, <code>Number.isNaN</code>) постійно трапляються у формах і API. Рядки для користувача у проєктах збирають шаблонними рядками, а не склеюванням через плюс.", "tasks": ["Напишіть функцію, що перетворює «іван петренко» на «Іван Петренко».", "Приймає рядок «12,5» і повертає число 12.5 (підказка: <code>replace</code>)."]}, "amethods": {"t": "Методи масивів: map, filter, reduce", "p": ["Основну роботу з масивами в сучасному JavaScript роблять методи вищого порядку. <code>map</code> перетворює кожен елемент, <code>filter</code> залишає потрібні, <code>find</code> знаходить перший відповідний, а <code>reduce</code> згортає масив до одного значення.", "Усі вони повертають новий результат і не змінюють початковий масив, а їх можна об'єднувати в ланцюжки. Метод <code>sort</code> змінює масив і потребує функції порівняння для чисел."], "code": ["const products = [\n  { id: 1, name: \"Зошит\", price: 40, inStock: true },\n  { id: 2, name: \"Ручка\", price: 15, inStock: false },\n  { id: 3, name: \"Рюкзак\", price: 650, inStock: true }\n];\n\nconst names = products.map(p => p.name);\nconst available = products.filter(p => p.inStock);\nconst bag = products.find(p => p.id === 3);\nconst total = available.reduce((sum, p) => sum + p.price, 0);\n\nconsole.log(names, available.length, bag.name, total);", "const cheapFirst = [...products].sort((a, b) => a.price - b.price);\nconsole.log(cheapFirst.map(p => p.name));\n\nconsole.log(products.some(p => p.price > 500));   // true\nconsole.log(products.every(p => p.price > 20));   // false\nconsole.log([1, 2, 3].includes(2));"], "note": "Щоб не змінити оригінальний масив під час сортування, робіть його копію через <code>[...arr]</code>.", "work": "Обробка списків (товари, користувачі, замовлення) — це найчастіша задача фронтенду. Код на кшталт «відфільтрувати, перетворити, порахувати» пишуть ланцюжком <code>filter().map().reduce()</code>, а на код-рев'ю не люблять ручні цикли з тимчасовими масивами.", "tasks": ["Із масиву товарів отримайте загальну вартість лише тих, що є в наявності.", "Відсортуйте масив користувачів за іменем, не змінюючи початковий масив."]}, "objects": {"t": "Об'єкти", "p": ["Об'єкт зберігає пари ключ-значення і описує одну сутність: користувача, товар, замовлення. До полів звертаються через крапку або квадратні дужки, а методи — це функції всередині об'єкта.", "Деструктуризація дістає потрібні поля в окремі змінні, а оператор розгортання <code>...</code> копіює об'єкт або об'єднує кілька. Методи <code>Object.keys</code>, <code>Object.values</code> і <code>Object.entries</code> перетворюють об'єкт на масив."], "code": ["const user = {\n  id: 7,\n  name: \"Олена\",\n  roles: [\"admin\", \"editor\"],\n  greet() { return \"Привіт, \" + this.name; }\n};\n\nconsole.log(user.name, user[\"id\"], user.greet());\n\nconst { name, roles } = user;\nconst copy = { ...user, name: \"Артем\" };\nconst withEmail = { ...user, email: \"o@x.ua\" };\nconsole.log(name, roles, copy.name, withEmail.email);", "const stock = { apples: 5, pears: 0, plums: 12 };\n\nfor (const [key, value] of Object.entries(stock)) {\n  console.log(key + \": \" + value);\n}\nconsole.log(Object.keys(stock).length);\nconsole.log(\"pears\" in stock, stock.kiwi === undefined);"], "note": "Копія через <code>{...obj}</code> неглибока: вкладені об'єкти й масиви в копії залишаються тими самими посиланнями.", "work": "Дані з API майже завжди приходять у вигляді масивів об'єктів, а вся робота з ними складається з деструктуризації, розгортання й методів масивів. Змінювати об'єкт «на місці» у спільному коді не люблять: створюють новий через <code>...</code> (це називають іммутабельністю).", "tasks": ["Опишіть об'єкт книги й виведіть його поля через Object.entries.", "Створіть копію об'єкта користувача зі зміненим email і переконайтеся, що оригінал не змінився."]}, "closure": {"t": "Область видимості та замикання", "p": ["Змінні, оголошені через <code>let</code> і <code>const</code>, видимі лише в блоці <code>{ }</code>, де їх створено. Змінні всередині функції недоступні ззовні, а внутрішня функція бачить змінні зовнішньої.", "Замикання виникає, коли функція «запам'ятовує» змінні з місця створення й користується ними навіть після завершення зовнішньої функції. Це основа приватних даних, фабрик функцій і багатьох бібліотек."], "code": ["function makeCounter() {\n  let count = 0;\n  return function () {\n    count++;\n    return count;\n  };\n}\n\nconst a = makeCounter();\nconst b = makeCounter();\nconsole.log(a(), a(), a());  // 1 2 3\nconsole.log(b());            // 1 — окремий лічильник", "function makeDiscount(percent) {\n  return price => price - price * percent / 100;\n}\nconst blackFriday = makeDiscount(30);\nconsole.log(blackFriday(200));  // 140\n\n{\n  const secret = 42;\n}\n// console.log(secret); // помилка: змінної немає поза блоком"], "note": "Старе ключове слово <code>var</code> має область видимості функції, а не блока, і піднімається нагору. Через це в нових проєктах його не використовують.", "work": "Про замикання питають і в кодовій базі, і на співбесідах, бо їх використовують обробники подій, <code>setTimeout</code>, хуки React та фабрики функцій. Типова помилка новачків — випадково зберегти застаріле значення змінної всередині такої функції.", "tasks": ["Напишіть makeMultiplier(n), що повертає функцію множення на n.", "Зробіть лічильник із методами increment, decrement та get, що ховає значення від прямого доступу."]}, "classes": {"t": "Класи та this", "p": ["Клас — це шаблон для створення однотипних об'єктів із даними й поведінкою. Метод <code>constructor</code> викликається під час створення екземпляра через <code>new</code>, а <code>this</code> вказує на цей екземпляр.", "Ключове слово <code>extends</code> дозволяє створити клас-нащадок, який успадковує поля й методи, а <code>super</code> викликає код батьківського класу. Статичні методи належать самому класу, а не екземпляру."], "code": ["class Account {\n  constructor(owner, balance = 0) {\n    this.owner = owner;\n    this.balance = balance;\n  }\n  deposit(amount) {\n    this.balance += amount;\n    return this;\n  }\n  describe() {\n    return this.owner + \": \" + this.balance + \" грн\";\n  }\n}\n\nconst acc = new Account(\"Олена\", 100);\nacc.deposit(50);\nconsole.log(acc.describe());", "class SavingsAccount extends Account {\n  constructor(owner, balance, rate) {\n    super(owner, balance);\n    this.rate = rate;\n  }\n  addInterest() {\n    this.balance += this.balance * this.rate;\n  }\n  static fromObject(o) {\n    return new SavingsAccount(o.owner, o.balance, o.rate);\n  }\n}\n\nconst s = SavingsAccount.fromObject({ owner: \"Артем\", balance: 1000, rate: 0.05 });\ns.addInterest();\nconsole.log(s.describe());"], "note": "Значення <code>this</code> залежить від того, як викликана функція. Якщо передати метод як окремий обробник, <code>this</code> втратиться: у таких випадках використовують стрілкові функції.", "work": "Класи в JavaScript застосовують помірно: у фронтенді частіше працюють функції й прості об'єкти, але у бекенді на Node.js, у TypeScript і в багатьох бібліотеках класи зустрічаються постійно. Прочитати чужий клас і зрозуміти <code>this</code> і <code>extends</code> — обов'язкова навичка.", "tasks": ["Створіть клас Product із методом, що рахує ціну зі знижкою.", "Додайте клас-нащадок DigitalProduct без доставки й перевизначте метод опису."]}, "errors": {"t": "Помилки та try/catch", "p": ["Помилки в роботі програм неминучі: недоступний сервер, некоректний ввід, відсутні дані. Блок <code>try/catch</code> перехоплює помилку, щоб програма не зупинялась, а <code>finally</code> виконується завжди.", "Власну помилку створюють через <code>throw new Error(\"повідомлення\")</code>. Типові повідомлення консолі, як-от <code>TypeError: Cannot read properties of undefined</code>, прямо вказують на рядок і причину, їх потрібно вміти читати."], "code": ["function parseAge(input) {\n  const age = Number(input);\n  if (Number.isNaN(age) || age < 0) {\n    throw new Error(\"Некоректний вік: \" + input);\n  }\n  return age;\n}\n\ntry {\n  console.log(parseAge(\"17\"));\n  console.log(parseAge(\"abc\"));\n} catch (e) {\n  console.log(\"Помилка:\", e.message);\n} finally {\n  console.log(\"Перевірка завершена\");\n}", "const raw = '{\"name\": \"Олена\"';   // зламаний JSON\ntry {\n  const data = JSON.parse(raw);\n  console.log(data);\n} catch (e) {\n  console.log(e.name);            // SyntaxError\n}\n\nconst user = undefined;\n// console.log(user.name);        // TypeError: Cannot read properties of undefined"], "note": "Не залишайте порожній блок <code>catch</code>. Принаймні виведіть помилку в консоль, інакше причину збою знайти буде майже неможливо.", "work": "Налагодження — до половини робочого часу розробника. Тому вчіться читати повідомлення про помилки та стек викликів у консолі браузера (F12), ставити точки зупину у вкладці Sources та передбачати помилки там, де працюєте з зовнішніми даними: JSON, мережа, ввід користувача.", "tasks": ["Напишіть функцію divide(a, b), що кидає помилку під час ділення на нуль, і обробіть її через try/catch.", "Спровокуйте TypeError і знайдіть у консолі рядок, що його викликав."]}, "modules": {"t": "Модулі та npm", "p": ["Реальні проєкти складаються з багатьох файлів. Модулі дозволяють розділити код: один файл експортує функції через <code>export</code>, інший підключає їх через <code>import</code>. Іменований експорт імпортують у фігурних дужках, а експорт за замовчуванням — без них.", "У браузері скрипт, що використовує модулі, підключають з атрибутом <code>type=\"module\"</code>. Сторонні бібліотеки встановлюють менеджером пакетів npm, який веде їхній список у файлі <code>package.json</code>."], "code": ["// math.js\nexport function add(a, b) {\n  return a + b;\n}\nexport const PI = 3.14159;\nexport default function square(x) {\n  return x * x;\n}\n\n// main.js\nimport square, { add, PI } from \"./math.js\";\nconsole.log(add(2, 3), square(4), PI);\n\n// index.html\n// <script type=\"module\" src=\"main.js\"></script>", "# термінал\nnpm init -y\nnpm install dayjs\nnpm install --save-dev prettier\nnpm run build"], "note": "Модулі працюють лише через веб-сервер (наприклад, <code>npx serve</code> або Live Server у VS Code), а не коли файл відкрито подвійним кліком.", "work": "У будь-якому робочому проєкті є <code>package.json</code>, папка <code>node_modules</code> (вона не потрапляє в Git) і розбиття коду на модулі. Уміння ініціалізувати проєкт, встановити залежність і зрозуміти скрипти з package.json очікують від кожного початківця.", "tasks": ["Винесіть дві функції в окремий файл і підключіть їх у main.js.", "Ініціалізуйте проєкт через npm і встановіть будь-яку бібліотеку на вибір."]}, "json": {"t": "JSON і localStorage", "p": ["JSON — текстовий формат обміну даними, який використовують майже всі API. Функція <code>JSON.stringify</code> перетворює об'єкт на рядок, а <code>JSON.parse</code> виконує зворотне перетворення.", "Браузер може зберігати дані між візитами в <code>localStorage</code>. Він зберігає лише рядки, тому об'єкти перед записом перетворюють через JSON."], "code": ["const todo = { id: 1, title: \"Вивчити JS\", done: false };\n\nconst text = JSON.stringify(todo);\nconsole.log(text);                 // {\"id\":1,\"title\":\"Вивчити JS\",\"done\":false}\n\nconst back = JSON.parse(text);\nconsole.log(back.title);", "function loadTodos() {\n  try {\n    return JSON.parse(localStorage.getItem(\"todos\")) ?? [];\n  } catch (e) {\n    return [];\n  }\n}\n\nfunction saveTodos(list) {\n  localStorage.setItem(\"todos\", JSON.stringify(list));\n}\n\nconst todos = loadTodos();\ntodos.push({ id: Date.now(), title: \"Новий пункт\", done: false });\nsaveTodos(todos);"], "note": "Не зберігайте в localStorage паролі й токени доступу: до нього може дістатися будь-який скрипт на сторінці.", "work": "Читання сховища завжди обгортають у try/catch, бо дані там можуть бути пошкоджені, а користувач може вимкнути сховище. Цей патерн «завантажити, змінити, зберегти» лежить в основі списків завдань, кошиків і налаштувань у більшості невеликих веб-застосунків.", "tasks": ["Збережіть налаштування теми (light/dark) у localStorage та прочитайте їх після перезавантаження.", "Додайте у список завдань видалення пункту з оновленням сховища."]}};
  o[0].work = "У командних проєктах за замовчуванням пишуть const, а let лише там, де значення справді змінюється. Слово var в новому коді не використовують. Імена змінних англійською в camelCase: userName, totalPrice.";
  o[1].work = "Функція має робити одну річ і мати зрозумілу назву-дієслово: calculateTotal, getUser. На код-рев'ю просять розбивати довгі функції на кілька коротких і не передавати занадто багато параметрів.";
  o[2].t = "Масиви"; o[2].work = "Масиви найчастіше містять об'єкти (список товарів, користувачів), тому майже кожну задачу з даними починають з перебору або перетворення масиву.";
  o[3].work = "У реальних проєктах на чистому DOM пишуть рідко: це основа, на якій тримаються React і Vue. Але розуміти querySelector і події треба, щоб налагоджувати будь-який фронтенд.";
  o[4].work = "Майже кожен запит до API у роботі пишеться через async/await з try/catch. Обов'язково перевіряють r.ok, бо fetch не кидає помилку на відповіді зі статусом 404 чи 500.";
  LESSONS.js = [o[0], N.cond, N.loops, o[1], N.strings, o[2], N.amethods, N.objects, N.closure, N.classes, N.errors, N.modules, o[3], N.json, o[4]];
  CHAPTERS.js = [["Основи", 0], ["Функції та дані", 3], ["Глибше в мову", 8], ["Браузер і мережа", 12]];
  CHAPTERS.js.forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS.js.length;
    for (let j = from; j < to; j++) LESSONS.js[j].ch = name;
  });
})();

/* ===== JavaScript: 22 уроки ===== */
(function () {
  const N = {"intro": {"t": "Де писати код: консоль, редактор, Node.js", "p": ["Перш ніж вчити мову, потрібно знати, де її запускати. JavaScript виконується в трьох місцях: у консолі браузера (клавіша F12, вкладка Console), у файлі на сторінці через тег <code>&lt;script&gt;</code> та в Node.js, який запускає код поза браузером.", "Для щоденної роботи встановіть редактор Visual Studio Code, а до нього розширення Live Server: воно відкриває сторінку в браузері й оновлює її після кожного збереження. Консоль зручна для швидких експериментів, а справжній код зберігають у файлах."], "code": ["// Вставте в консоль браузера (F12 → Console) і натисніть Enter\nconsole.log(\"Привіт, JavaScript!\");\n2 + 3\n\"Ім'я\".length", "<!-- index.html -->\n<!DOCTYPE html>\n<html lang=\"uk\">\n<head><meta charset=\"utf-8\"><title>Тест</title></head>\n<body>\n  <h1 id=\"title\">Привіт</h1>\n  <script src=\"script.js\"></script>\n</body>\n</html>\n\n// script.js\ndocument.getElementById(\"title\").textContent = \"Працює!\";\nconsole.log(\"Скрипт підключено\");"], "note": "Тег <code>&lt;script&gt;</code> зазвичай ставлять наприкінці <code>body</code>, щоб до запуску скрипта елементи вже існували на сторінці.", "easy": "Код — це список інструкцій для комп'ютера. Консоль браузера — це блокнот, куди можна записати одну інструкцію й одразу побачити, що вийшло.", "work": "Розробник щодня працює в трьох місцях: редактор коду (VS Code), браузер із відкритими DevTools і термінал. Навчіться швидко відкривати консоль і бачити в ній помилки: це перше, що роблять, коли «щось не працює».", "tasks": ["Відкрийте консоль і виведіть через console.log своє ім'я.", "Створіть index.html зі script.js і змініть текст заголовка зі скрипта."]}, "setmap": {"t": "Set і Map", "p": ["Окрім масивів і об'єктів, у JavaScript є дві корисні колекції. <code>Set</code> зберігає лише унікальні значення, тому дублікати зникають автоматично. <code>Map</code> — це словник, у якого ключем може бути будь-що, а не лише рядок.", "Обидві колекції мають методи <code>add</code>/<code>set</code>, <code>has</code>, <code>delete</code> і властивість <code>size</code>, а перебирати їх можна циклом <code>for...of</code>."], "code": ["const tags = new Set([\"js\", \"css\", \"js\", \"html\", \"css\"]);\nconsole.log(tags.size);          // 3\nconsole.log(tags.has(\"css\"));    // true\ntags.add(\"php\");\n\nconst unique = [...new Set([1, 2, 2, 3, 3, 3])];\nconsole.log(unique);             // [1, 2, 3]", "const users = new Map();\nusers.set(101, { name: \"Олена\" });\nusers.set(102, { name: \"Артем\" });\n\nconsole.log(users.get(101).name);\nconsole.log(users.has(103));\n\nfor (const [id, user] of users) {\n  console.log(id, user.name);\n}"], "note": "Найшвидший спосіб прибрати дублікати з масиву — перетворити його на Set і назад: <code>[...new Set(arr)]</code>.", "easy": "Set — це список без повторів, як перелік гостей, де кожне ім'я записують один раз. Map — словник: за ключем швидко знаходиться значення.", "work": "Set використовують, щоб прибирати дублікати та швидко перевіряти «чи вже є таке значення». Map зручний, коли дані шукають за ідентифікатором, наприклад користувачів за id: це швидше й чистіше, ніж щоразу шукати в масиві через find.", "tasks": ["Прибрайте дублікати з масиву імен, що містить повтори.", "Збережіть у Map три товари за їхнім id і знайдіть один із них."]}, "date": {"t": "Дата й час", "p": ["Для роботи з датами є вбудований об'єкт <code>Date</code>. Новий екземпляр без аргументів містить поточний момент, а з аргументом — вказану дату. Усередині дата зберігається як кількість мілісекунд від 1 січня 1970 року.", "Для виведення користувачу застосовують <code>toLocaleDateString</code> із мовою, а для передачі на сервер — формат ISO, який дає <code>toISOString</code>."], "code": ["const now = new Date();\nconsole.log(now.getFullYear(), now.getMonth() + 1, now.getDate());\n\nconst exam = new Date(\"2026-12-20\");\nconsole.log(exam.toLocaleDateString(\"uk-UA\", {\n  day: \"numeric\", month: \"long\", year: \"numeric\"\n}));\nconsole.log(now.toISOString());", "const day = 24 * 60 * 60 * 1000;\nconst left = Math.ceil((exam - now) / day);\nconsole.log(\"До іспиту днів:\", left);\n\nconst next = new Date(now);\nnext.setDate(next.getDate() + 7);\nconsole.log(\"Через тиждень:\", next.toLocaleDateString(\"uk-UA\"));"], "note": "Місяці в JavaScript нумеруються з нуля: січень — це 0, а грудень — 11. Саме тому до <code>getMonth()</code> додають 1.", "easy": "Дата в JavaScript — це просто велике число мілісекунд від 1 січня 1970 року. Усе інше — лише спосіб гарно її показати.", "work": "Дати постійно ходять між фронтендом і сервером: у запитах їх передають у форматі ISO, а користувачу показують у його мові та часовому поясі. Для складних обчислень у проєктах часто беруть бібліотеку на кшталт dayjs, але основу <code>Date</code> знати потрібно.", "tasks": ["Виведіть, скільки днів залишилось до вашого дня народження.", "Покажіть поточну дату у форматі «5 жовтня 2026»."]}, "forms": {"t": "Форми та делегування подій", "p": ["Подія <code>submit</code> форми за замовчуванням перезавантажує сторінку, тому в обробнику викликають <code>event.preventDefault()</code>. Значення полів зручно зібрати через <code>FormData</code>.", "Якщо в списку багато елементів, не вішають окремий обробник на кожен. Один обробник ставлять на батьківський елемент і дивляться, куди клікнули, через <code>event.target</code>. Це називають делегуванням подій."], "code": ["<form id=\"signup\">\n  <input name=\"email\" type=\"email\" required>\n  <input name=\"age\" type=\"number\" min=\"1\">\n  <button>Надіслати</button>\n</form>\n<p id=\"msg\"></p>\n\n<script>\n  const form = document.querySelector(\"#signup\");\n  form.addEventListener(\"submit\", e => {\n    e.preventDefault();\n    const data = Object.fromEntries(new FormData(form));\n    const msg = document.querySelector(\"#msg\");\n    msg.textContent = data.age < 14 ? \"Замало років\" : \"Дякуємо, \" + data.email;\n  });\n</script>", "<ul id=\"list\">\n  <li data-id=\"1\">Зошит <button class=\"del\">×</button></li>\n  <li data-id=\"2\">Ручка <button class=\"del\">×</button></li>\n</ul>\n\n<script>\n  document.querySelector(\"#list\").addEventListener(\"click\", e => {\n    const btn = e.target.closest(\".del\");\n    if (!btn) return;\n    btn.closest(\"li\").remove();\n  });\n</script>"], "note": "Список може змінюватися (елементи додаються й видаляються), а делегування працює і для нових елементів без додаткового коду.", "easy": "Делегування — це один сторож на весь коридор замість окремого сторожа біля кожних дверей: він бачить, у які двері постукали.", "work": "Форми — найчастіша задача веб-розробника: реєстрація, пошук, замовлення. Типовий процес: перехопити submit, зібрати дані, перевірити їх, показати помилки біля полів і лише потім надсилати на сервер.", "tasks": ["Зробіть форму входу, що виводить помилку, якщо пароль коротший за 6 символів.", "Додайте до списку кнопку видалення через делегування подій."]}, "eventloop": {"t": "Як працює асинхронність: таймери та черга подій", "p": ["JavaScript виконує код по одному рядку за раз, не вміючи робити дві речі одночасно. Довгі дії, наприклад таймер або запит до сервера, він передає браузеру й повертається до них, коли результат готовий.", "Функція <code>setTimeout</code> відкладає виконання коду, а колбек (функція, яку потрібно викликати пізніше) потрапляє в чергу й запускається лише тоді, коли основний код завершився. Саме тому <code>setTimeout(fn, 0)</code> усе одно виконається після решти поточного коду."], "code": ["console.log(\"1. Початок\");\n\nsetTimeout(() => {\n  console.log(\"3. Через таймер\");\n}, 0);\n\nconsole.log(\"2. Кінець\");\n// Порядок виводу: 1, 2, 3", "let seconds = 3;\nconst timer = setInterval(() => {\n  console.log(\"Залишилось:\", seconds);\n  seconds--;\n  if (seconds < 0) {\n    clearInterval(timer);\n    console.log(\"Старт!\");\n  }\n}, 1000);"], "note": "Таймер, який більше не потрібен, зупиняють через <code>clearTimeout</code> або <code>clearInterval</code>, інакше він працюватиме нескінченно.", "easy": "JavaScript — це кухар з однією парою рук. Довгі справи (запити, таймери) він віддає помічникові-браузеру й береться до них знову, коли ті готові.", "work": "Розуміння цього порядку виконання допомагає зрозуміти, чому дані «ще не прийшли», коли ви звертаєтесь до них, і чому код виконується не в тому порядку, у якому записаний. Це одне з найпоширеніших джерел помилок у початківців.", "tasks": ["Передбачте порядок виводу трьох console.log, один з яких у setTimeout, і перевірте себе.", "Зробіть таймер зворотного відліку від 10 до 0."]}, "api": {"t": "Запити до API: GET і POST", "p": ["API — це спосіб, яким фронтенд спілкується із сервером. Запит <code>GET</code> отримує дані, <code>POST</code> створює нові, <code>PUT</code>/<code>PATCH</code> оновлюють, а <code>DELETE</code> видаляє. Відповідь сервера має код статусу: 2xx означає успіх, 4xx — помилку у запиті, 5xx — помилку сервера.", "Для POST передають метод, заголовок <code>Content-Type</code> і тіло запиту у вигляді JSON-рядка. Найважливіше правило: завжди перевіряйте <code>response.ok</code>, бо fetch не вважає помилкою відповідь 404 чи 500."], "code": ["const API = \"https://jsonplaceholder.typicode.com\";\n\nasync function getPosts() {\n  const r = await fetch(API + \"/posts?_limit=3\");\n  if (!r.ok) throw new Error(\"Помилка сервера: \" + r.status);\n  return r.json();\n}\n\ngetPosts()\n  .then(posts => console.log(posts.map(p => p.title)))\n  .catch(e => console.log(e.message));", "async function createPost(title, body) {\n  const r = await fetch(API + \"/posts\", {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify({ title, body, userId: 1 })\n  });\n  if (!r.ok) throw new Error(\"Не вдалося створити: \" + r.status);\n  return r.json();\n}\n\ncreatePost(\"Привіт\", \"Мій перший пост\")\n  .then(p => console.log(\"Створено, id:\", p.id))\n  .catch(e => console.log(e.message));"], "note": "Типові статуси: 200 — успіх, 201 — створено, 400 — некоректний запит, 401 — потрібна авторизація, 404 — не знайдено, 500 — збій на сервері.", "easy": "API — це меню ресторану: ви робите замовлення (запит) за правилами, а кухня (сервер) повертає страву (відповідь) або каже, що її немає.", "work": "Майже кожен фронтенд працює з API. У проєктах запити виносять в окремі функції чи модуль, обробляють помилки й показують користувачу повідомлення «Спробуйте пізніше», а також індикатор завантаження, поки чекають відповідь.", "tasks": ["Завантажте список користувачів із jsonplaceholder і виведіть їхні імена.", "Надішліть POST-запит і виведіть id створеного ресурсу."]}, "devtools": {"t": "Налагодження: DevTools у браузері", "p": ["DevTools відкриваються клавішею F12. Вкладка <code>Elements</code> показує структуру сторінки й стилі, <code>Console</code> — повідомлення та помилки, <code>Network</code> — усі запити з їхніми статусами й відповідями, <code>Sources</code> — код зі зручним налагоджувачем.", "Налагоджувати можна двома способами. Швидкий — вивести значення через <code>console.log</code>. Надійніший — поставити точку зупину: клікнути на номер рядка у вкладці Sources або написати в коді <code>debugger</code>. Виконання зупиниться, і ви побачите значення всіх змінних."], "code": ["const orders = [\n  { id: 1, customer: \"Олена\", total: 450 },\n  { id: 2, customer: \"Артем\", total: 120 }\n];\n\nconsole.table(orders);\nconsole.error(\"Це повідомлення про помилку\");\nconsole.warn(\"А це попередження\");\n\nfunction calc(items) {\n  let sum = 0;\n  for (const o of items) {\n    debugger;          // виконання зупиниться тут\n    sum += o.total;\n  }\n  return sum;\n}\nconsole.log(calc(orders));"], "note": "Після налагодження видаліть із коду всі <code>debugger</code> і зайві <code>console.log</code>: у готовому проєкті їм не місце.", "easy": "DevTools — це рентген для сторінки: ви бачите, що відбувається всередині коду, стилів і мережі, і знаходите, де саме зламалось.", "work": "Уміння налагоджувати відрізняє початківця від того, кого беруть на роботу. Типовий алгоритм: відкрити Console і прочитати помилку, у Network перевірити, чи пішов запит і що відповів сервер, а потім за допомогою точки зупину знайти рядок, де значення стало неправильним.", "tasks": ["Відкрийте будь-який сайт і в Network знайдіть запит, що повернув JSON.", "Поставте точку зупину у своєму циклі й подивіться значення змінної на кожній ітерації."]}};
  const easyOld = {"Змінні та типи в JavaScript": "Змінна — це підписана коробка, у яку кладуть значення. Коробка const запечатана назавжди, а коробку let можна відкрити й змінити вміст.", "Умови та оператори": "Умова — це розвилка на дорозі: якщо щось правда, ідемо в один бік, якщо ні — в інший.", "Цикли": "Цикл — це команда «повторюй ці дії», доки не виконається умова зупинки.", "Функції": "Функція — це рецепт: ви один раз записуєте кроки й потім готуєте за ним скільки завгодно разів, змінюючи інгредієнти (параметри).", "Рядки та числа": "Рядок — це текст, а метод — готова дія над ним, як кнопка на калькуляторі.", "Масиви": "Масив — це нумерований список, як перелік покупок, тільки нумерація починається не з одиниці, а з нуля.", "Методи масивів: map, filter, reduce": "map перетворює кожен елемент, filter залишає потрібні, а reduce зводить усе до одного підсумку, як касир, що рахує загальну суму чека.", "Об'єкти": "Об'єкт — це картка з полями, як анкета: ім'я, вік, пошта. Кожне поле має свою назву й значення.", "Область видимості та замикання": "Замикання — це рюкзак, який функція бере з собою з місця народження: у ньому лежать потрібні їй змінні.", "Класи та this": "Клас — це креслення, за яким можна зробити багато однакових предметів. <code>this</code> — це «саме цей предмет».", "Помилки та try/catch": "try/catch — це страхувальна сітка: якщо щось падає, програма не розбивається, а ловить помилку й продовжує.", "Модулі та npm": "Модуль — це окремий файл-інструмент, який підключають до основного коду, як шухляду з інструментами. npm — магазин, де можна взяти чужі інструменти.", "DOM і події": "DOM — це дерево елементів сторінки, а JavaScript — пульт, яким ними керують: змінюють текст, кольори, реагують на кліки.", "JSON і localStorage": "JSON — це текст, у який упаковані дані для передачі, як посилка. localStorage — шухляда браузера для невеликих речей.", "Проміси, async та fetch": "Проміс — це квитанція: результату ще немає, але його обіцяють видати пізніше. await означає «зачекай, поки видадуть»."};
  const byTitle = {};
  LESSONS.js.forEach(l => { byTitle[l.t] = l; if (easyOld[l.t]) l.easy = easyOld[l.t]; });
  const T = t => { if (!byTitle[t]) throw new Error("Немає уроку: " + t); return byTitle[t]; };
  LESSONS.js = [N.intro, T("Змінні та типи в JavaScript"), T("Умови та оператори"), T("Цикли"),
    T("Функції"), T("Рядки та числа"), T("Масиви"), T("Методи масивів: map, filter, reduce"), T("Об'єкти"), N.setmap, N.date,
    T("Область видимості та замикання"), T("Класи та this"), T("Помилки та try/catch"), T("Модулі та npm"),
    T("DOM і події"), N.forms, T("JSON і localStorage"),
    N.eventloop, T("Проміси, async та fetch"), N.api, N.devtools];
  CHAPTERS.js = [["Початок", 0], ["Функції та дані", 4], ["Глибше в мову", 11], ["Браузер", 15], ["Асинхронність і API", 18], ["Налагодження", 21]];
  CHAPTERS.js.forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS.js.length;
    for (let j = from; j < to; j++) LESSONS.js[j].ch = name;
  });
})();

/* ===== TypeScript: 12 уроків ===== */
(function () {
  const N = {"setup": {"t": "Встановлення та налаштування", "p": ["TypeScript працює через компілятор: ви пишете файли <code>.ts</code>, а він перевіряє типи й створює звичайний JavaScript. Потрібен лише Node.js: після його встановлення компілятор додають у проєкт командами нижче.", "Налаштування компілятора зберігаються у файлі <code>tsconfig.json</code>. Найважливіший параметр — <code>\"strict\": true</code>: він вмикає суворі перевірки, які ловлять більшість помилок."], "code": ["# термінал\nmkdir ts-demo && cd ts-demo\nnpm init -y\nnpm install --save-dev typescript\nnpx tsc --init\n\n# hello.ts\nconst message: string = \"Привіт, TypeScript!\";\nconsole.log(message);\n\n# компіляція та запуск\nnpx tsc\nnode hello.js", "// tsconfig.json (скорочено)\n{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"module\": \"commonjs\",\n    \"outDir\": \"dist\",\n    \"strict\": true\n  },\n  \"include\": [\"src\"]\n}"], "note": "Для швидкого запуску без окремої компіляції можна скористатись командою <code>npx tsx hello.ts</code>.", "easy": "TypeScript — це перекладач із суворим коректором: ви пишете код із типами, він знаходить помилки й видає звичайний JavaScript.", "work": "У будь-якому робочому проєкті є <code>tsconfig.json</code>, а режим <code>strict</code> майже завжди увімкнений. Помилки компілятора читають так само уважно, як помилки в консолі: у них вказано файл, рядок і причину.", "tasks": ["Створіть проєкт, скомпілюйте hello.ts і запустіть результат.", "Увімкніть strict і подивіться, які помилки з'являються у вашому коді."]}, "basic": {"t": "Базові типи", "p": ["Прості типи — <code>string</code>, <code>number</code>, <code>boolean</code>. Масив записують як <code>number[]</code>, а кортеж — як масив фіксованої довжини з типом кожного елемента: <code>[string, number]</code>.", "Тип <code>any</code> вимикає перевірки й його варто уникати. Замість нього використовують <code>unknown</code>: значення невідомого типу, яке перед використанням потрібно перевірити. Типи часто не пишуть явно, бо TypeScript сам виводить їх зі значення."], "code": ["let title: string = \"Курс\";\nlet price: number = 199;\nlet isFree: boolean = false;\n\nconst tags: string[] = [\"ts\", \"js\"];\nconst point: [number, number] = [10, 20];\n\nenum Role { Admin, Editor, Viewer }\nconst r: Role = Role.Editor;\n\nlet inferred = 42;      // TypeScript сам визначив: number\n// inferred = \"сорок\";  // помилка", "let value: unknown = \"текст\";\n// console.log(value.length);  // помилка: тип невідомий\n\nif (typeof value === \"string\") {\n  console.log(value.length);   // тепер можна\n}\n\nfunction fail(msg: string): never {\n  throw new Error(msg);\n}"], "note": "Явні типи потрібні для параметрів функцій і публічних даних, а для звичайних локальних змінних їх зазвичай не вказують.", "easy": "Тип каже, що саме лежить у змінній: число, текст чи список. Якщо покласти не те, компілятор одразу підкаже.", "work": "Тип <code>any</code> на код-рев'ю викликає питання, тому в командах вважається поганим тоном. Якщо тип справді невідомий, беруть <code>unknown</code> і перевіряють його.", "tasks": ["Опишіть змінні для імені, віку та списку навичок з правильними типами.", "Перевірте, що буде, якщо присвоїти рядок змінній типу number."]}, "funcs": {"t": "Типізація функцій", "p": ["У функції типізують параметри та значення, що повертається. Необов'язковий параметр позначають знаком <code>?</code>, а значення за замовчуванням задають через <code>=</code>. Якщо функція нічого не повертає, її тип результату — <code>void</code>.", "Тип самої функції записують у вигляді <code>(a: number) =&gt; string</code>. Так описують колбеки, які передають в інші функції."], "code": ["function add(a: number, b: number): number {\n  return a + b;\n}\n\nfunction greet(name: string, greeting: string = \"Привіт\"): string {\n  return greeting + \", \" + name;\n}\n\nfunction log(msg: string, level?: string): void {\n  console.log((level ?? \"info\") + \": \" + msg);\n}", "type Mapper = (n: number) => string;\n\nfunction convert(list: number[], fn: Mapper): string[] {\n  return list.map(fn);\n}\nconsole.log(convert([1, 2, 3], n => \"№\" + n));\n\nconst sum = (...nums: number[]): number =>\n  nums.reduce((s, n) => s + n, 0);\nconsole.log(sum(1, 2, 3));"], "note": "Параметри стрілкових функцій у колбеках часто типізувати не треба: TypeScript бере тип із контексту.", "easy": "Типи в сигнатурі функції — це договір: що вона приймає на вході й що гарантовано поверне.", "work": "Читаючи чужий код, ви спершу дивитесь на сигнатури функцій: за ними видно, як ними користуватися, не заглядаючи всередину. Тому в командах просять завжди типізувати параметри та результат експортованих функцій.", "tasks": ["Напишіть функцію average(nums: number[]): number.", "Опишіть тип колбека для кнопки, що приймає рядок і нічого не повертає."]}, "narrow": {"t": "Звуження типів", "p": ["Коли значення має кілька можливих типів, TypeScript дозволяє лише спільні дії. Щоб скористатись конкретними, потрібно звузити тип перевіркою: <code>typeof</code>, <code>instanceof</code>, <code>in</code> або порівнянням.", "Особливо зручні розрізнювані об'єднання: кожен варіант має спільне поле-мітку (наприклад <code>kind</code>), за яким компілятор точно знає, з яким варіантом працює."], "code": ["type Circle = { kind: \"circle\"; radius: number };\ntype Square = { kind: \"square\"; side: number };\ntype Shape = Circle | Square;\n\nfunction area(s: Shape): number {\n  if (s.kind === \"circle\") {\n    return Math.PI * s.radius ** 2;\n  }\n  return s.side ** 2;\n}\n\nconsole.log(area({ kind: \"circle\", radius: 2 }));", "function process(v: string | string[] | null): string {\n  if (v === null) return \"порожньо\";\n  if (Array.isArray(v)) return v.join(\", \");\n  return v.toUpperCase();\n}\n\nfunction assertNever(x: never): never {\n  throw new Error(\"Невідомий варіант: \" + x);\n}"], "note": "Якщо додати новий варіант у об'єднання, а перевірку за <code>never</code> залишити, компілятор вкаже всі місця, які треба оновити.", "easy": "Звуження — це перевірка пропуску на вході: після неї компілятор точно знає, хто перед ним, і дозволяє відповідні дії.", "work": "Розрізнювані об'єднання — стандартний спосіб описати стани: «завантажується», «успіх», «помилка». Такий підхід широко застосовують у React-проєктах і при роботі з відповідями API.", "tasks": ["Опишіть тип Result із варіантами success (з даними) та error (з повідомленням) і функцію, що його обробляє.", "Додайте до Shape третій варіант і подивіться, що скаже компілятор."]}, "alias": {"t": "type та interface: розширення і перетини", "p": ["Псевдонім <code>type</code> дає ім'я будь-якому типу: об'єднанню, кортежу чи об'єкту. Інтерфейс <code>interface</code> описує тільки форму об'єкта, зате вміє розширюватись ключовим словом <code>extends</code>.", "Перетин <code>A &amp; B</code> створює тип, що має поля обох. Модифікатор <code>readonly</code> забороняє змінювати поле після створення."], "code": ["interface Entity {\n  readonly id: number;\n}\n\ninterface User extends Entity {\n  name: string;\n  email?: string;\n}\n\ntype Timestamps = { createdAt: Date; updatedAt: Date };\ntype UserRecord = User & Timestamps;\n\nconst rec: UserRecord = {\n  id: 1, name: \"Олена\",\n  createdAt: new Date(), updatedAt: new Date()\n};\n// rec.id = 2; // помилка: readonly", "type Id = number | string;\ntype Handler = (event: string) => void;\n\nconst scores: Record<string, number> = { anna: 90, taras: 75 };\nscores[\"olena\"] = 82;"], "note": "Правило для вибору: для об'єктів зазвичай беруть <code>interface</code>, для об'єднань, функцій та інших типів — <code>type</code>. Головне — дотримуватись одного стилю в проєкті.", "easy": "interface і type майже взаємозамінні: interface звик описувати об'єкти, а type — усе інше, зокрема варіанти «або».", "work": "Загальні поля (id, дати створення) виносять в окремий базовий тип і розширюють ним решту типів. Так не доводиться повторювати однаковий опис у десятках місць.", "tasks": ["Опишіть Product, що розширює базовий Entity, і додайте readonly-поле.", "Створіть тип-словник Record<string, boolean> для прапорців функцій."]}, "classes": {"t": "Класи в TypeScript", "p": ["У класах TypeScript поля та методи мають модифікатори доступу: <code>public</code> (за замовчуванням), <code>private</code> (лише всередині класу) і <code>protected</code> (у класі та нащадках). Модифікатор <code>readonly</code> забороняє змінювати поле.", "Параметри конструктора з модифікатором автоматично стають полями класу, тому код стає коротшим. Клас може реалізувати інтерфейс через <code>implements</code>: компілятор перевірить, що всі потрібні методи є."], "code": ["class Account {\n  private balance = 0;\n\n  constructor(public readonly owner: string) {}\n\n  deposit(amount: number): void {\n    if (amount <= 0) throw new Error(\"Сума має бути додатною\");\n    this.balance += amount;\n  }\n  getBalance(): number {\n    return this.balance;\n  }\n}\n\nconst acc = new Account(\"Олена\");\nacc.deposit(100);\nconsole.log(acc.getBalance());\n// acc.balance = 5; // помилка: private", "interface Logger {\n  log(message: string): void;\n}\n\nclass ConsoleLogger implements Logger {\n  log(message: string): void {\n    console.log(\"[LOG]\", message);\n  }\n}"], "note": "Модифікатор <code>private</code> діє лише на етапі компіляції. Для справжньої приватності на рівні JavaScript використовують поля з символом <code>#</code>.", "easy": "Модифікатори доступу — це замки на дверях класу: private відчиняється лише зсередини.", "work": "Класи з <code>private</code>-полями та інтерфейсами — основа backend-проєктів на TypeScript, зокрема Node.js фреймворків NestJS і Angular. Запис <code>constructor(private service: Service)</code> ви побачите в них на кожному кроці.", "tasks": ["Напишіть клас Timer з приватним полем лічильника та методами start і stop.", "Опишіть інтерфейс Storage і дві його реалізації: у пам'яті та в localStorage."]}, "utility": {"t": "Утилітарні типи", "p": ["Утилітарні типи — це готові «функції для типів», які створюють новий тип на основі наявного. <code>Partial&lt;T&gt;</code> робить усі поля необов'язковими, <code>Required&lt;T&gt;</code> — обов'язковими, <code>Readonly&lt;T&gt;</code> — незмінними.", "<code>Pick&lt;T, Keys&gt;</code> залишає лише вказані поля, <code>Omit&lt;T, Keys&gt;</code> прибирає їх, а <code>Record&lt;K, V&gt;</code> створює словник. Їхня головна цінність — не копіювати той самий тип вручну."], "code": ["interface User {\n  id: number;\n  name: string;\n  email: string;\n  password: string;\n}\n\ntype UserUpdate = Partial<User>;                      // усі поля необов'язкові\ntype PublicUser = Omit<User, \"password\">;             // без пароля\ntype UserPreview = Pick<User, \"id\" | \"name\">;\ntype UserMap = Record<number, PublicUser>;\n\nfunction update(id: number, changes: UserUpdate) {\n  console.log(\"Оновлюємо\", id, changes);\n}\nupdate(1, { name: \"Нове ім'я\" });", "const config: Readonly<{ url: string; retries: number }> = {\n  url: \"https://api.example.com\",\n  retries: 3\n};\n// config.retries = 5; // помилка\n\ntype Fn = (a: number) => string;\ntype Result = ReturnType<Fn>;   // string"], "note": "Утилітарні типи можна комбінувати: наприклад, <code>Partial&lt;Omit&lt;User, \"id\"&gt;&gt;</code> підходить для форми редагування.", "easy": "Утилітарні типи — це готові інструменти для перетворення вже наявних типів, як фільтри в фоторедакторі.", "work": "Для форм редагування, відповідей API без чутливих полів і словників даних утилітарні типи використовують постійно. Вони зменшують дублювання, а значить і ризик розбіжності між типами.", "tasks": ["Створіть тип для оновлення товару через Partial та Omit.", "Зробіть тип публічного профілю без поля email."]}, "apits": {"t": "TypeScript у реальному проєкті: API та модулі", "p": ["Дані із сервера TypeScript не перевіряє: метод <code>response.json()</code> повертає <code>any</code>. Тому форму відповіді описують інтерфейсом, а в критичних місцях додатково перевіряють дані під час виконання.", "Типи між файлами передають тими самими <code>export</code> та <code>import</code>. Для бібліотек на чистому JavaScript існують пакети з типами <code>@types/…</code>, які встановлюють як dev-залежність."], "code": ["// types.ts\nexport interface Post {\n  id: number;\n  title: string;\n  body: string;\n}\n\n// api.ts\nimport type { Post } from \"./types\";\n\nconst API = \"https://jsonplaceholder.typicode.com\";\n\nexport async function getPost(id: number): Promise<Post> {\n  const r = await fetch(API + \"/posts/\" + id);\n  if (!r.ok) throw new Error(\"Помилка: \" + r.status);\n  const data: unknown = await r.json();\n  if (!isPost(data)) throw new Error(\"Некоректна відповідь сервера\");\n  return data;\n}\n\nfunction isPost(v: unknown): v is Post {\n  return typeof v === \"object\" && v !== null &&\n    typeof (v as Post).id === \"number\" &&\n    typeof (v as Post).title === \"string\";\n}", "# термінал\nnpm install --save-dev @types/node\nnpm install axios        # у багатьох бібліотек типи вже вбудовані"], "note": "Функція з типом результату <code>v is Post</code> називається захисником типу: після її успішної перевірки компілятор вважає значення типом Post.", "easy": "Дані із сервера — це чорна скринька: TypeScript не знає, що в ній, доки ви не опишете й не перевірите вміст.", "work": "Розбіжність між типом на фронтенді та реальною відповіддю сервера — одна з найпоширеніших причин багів. У командах типи для API часто генерують із специфікації, а в невеликих проєктах описують вручну й перевіряють на вході.", "tasks": ["Опишіть інтерфейс користувача з jsonplaceholder і напишіть типізовану функцію getUser.", "Додайте захисник типу, що перевіряє наявність полів id та name."]}};
  const easyOld = {"Від JavaScript до TypeScript": "Типи — це етикетки на коробках: компілятор не дозволить покласти слова в коробку з написом «число».", "Union-типи та літерали": "Union — це «або»: значення може бути одним з кількох заздалегідь описаних варіантів.", "Інтерфейси та об'єкти": "Інтерфейс — це анкета-шаблон: які поля обов'язкові, які ні і якого типу кожне.", "Узагальнення (generics)": "Generic — це шаблон із порожнім місцем для типу: функцію пишуть один раз, а працює вона з будь-яким типом."};
  const workOld = {"Від JavaScript до TypeScript": "Більшість нових вакансій для веброзробників згадують TypeScript. Поступовий перехід нормальний: у проєкті файли <code>.js</code> і <code>.ts</code> можуть співіснувати, а типи додають по одному файлу.", "Union-типи та літерали": "Літеральні типи замінюють «магічні рядки»: замість довільного тексту статус замовлення можна обрати лише з дозволеного списку, а опечатку компілятор помітить одразу.", "Інтерфейси та об'єкти": "Інтерфейси — це документація для колег: за ними видно, які дані очікує компонент або функція, і не потрібно вгадувати форму об'єкта.", "Узагальнення (generics)": "Generics ви побачите в Promise&lt;T&gt;, Array&lt;T&gt; та в бібліотеках на кшталт React. Писати власні потрібно рідше, але читати їх обов'язково."};
  const byTitle = {};
  LESSONS.ts.forEach(l => { byTitle[l.t] = l; l.easy = easyOld[l.t]; l.work = workOld[l.t]; });
  const T = t => { if (!byTitle[t]) throw new Error("Немає уроку: " + t); return byTitle[t]; };
  LESSONS.ts = [N.setup, T("Від JavaScript до TypeScript"), N.basic, N.funcs, T("Union-типи та літерали"), N.narrow,
    T("Інтерфейси та об'єкти"), N.alias, N.classes, T("Узагальнення (generics)"), N.utility, N.apits];
  CHAPTERS.ts = [["Початок", 0], ["Типи", 2], ["Структури даних", 6], ["Просунуті можливості", 9]];
  CHAPTERS.ts.forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS.ts.length;
    for (let j = from; j < to; j++) LESSONS.ts[j].ch = name;
  });
})();

/* ===== Python: 20 уроків ===== */
(function () {
  const N = {"install": {"t": "Встановлення Python і перший запуск", "p": ["Python безкоштовний. Завантажте інсталятор із python.org і під час встановлення на Windows обов'язково поставте галочку <b>Add Python to PATH</b>. Перевірити встановлення можна в терміналі командою <code>python --version</code>.", "Код можна виконувати двома способами: вводити рядки по одному в інтерактивному режимі (REPL) або зберегти їх у файл <code>.py</code> і запустити. Для роботи встановіть редактор VS Code з розширенням Python."], "code": ["# термінал\npython --version\npython            # відкриває інтерактивний режим\n>>> 2 + 3\n5\n>>> exit()\n\n# файл hello.py\nprint(\"Привіт, Python!\")\n\n# запуск\npython hello.py"], "note": "На macOS і Linux команда часто називається <code>python3</code>. Якщо <code>python</code> не знайдено, спробуйте її.", "easy": "Python — це перекладач: ви пишете зрозумілі рядки, а він виконує їх по одному. REPL — це чернетка, де можна швидко спробувати будь-яку команду.", "work": "Розробник працює в редакторі й терміналі одночасно: пише код у VS Code, а запускає й тестує командами. Тому одразу привчайтесь запускати файли з термінала, а не лише кнопкою в редакторі.", "tasks": ["Встановіть Python і виведіть його версію в терміналі.", "Створіть файл hello.py і запустіть його."]}, "tuples": {"t": "Кортежі та множини", "p": ["Кортеж схожий на список, але незмінний: після створення його елементи змінити не можна. Його записують у круглих дужках і часто використовують для невеликих наборів даних, наприклад координат. Кортеж можна «розпакувати» у кілька змінних одразу.", "Множина зберігає лише унікальні значення без порядку. Вона швидко перевіряє наявність елемента й підтримує операції з теорії множин: об'єднання <code>|</code>, перетин <code>&amp;</code>, різницю <code>-</code>."], "code": ["point = (10, 20)\nx, y = point\nprint(x, y)\n# point[0] = 5   # помилка: кортеж не змінюється\n\ndef min_max(nums):\n    return min(nums), max(nums)   # повертає кортеж\n\nlow, high = min_max([4, 9, 1])\nprint(low, high)", "tags = {\"python\", \"sql\", \"python\", \"git\"}\nprint(tags, len(tags))\ntags.add(\"docker\")\nprint(\"sql\" in tags)\n\na = {1, 2, 3}\nb = {3, 4}\nprint(a | b, a & b, a - b)\n\nunique = list(set([1, 1, 2, 3, 3]))\nprint(unique)"], "note": "Порожню множину створюють як <code>set()</code>, а не <code>{}</code>: фігурні дужки без вмісту створюють словник.", "easy": "Кортеж — це запечатаний конверт: вміст можна прочитати, але не змінити. Множина — список гостей, де кожне ім'я записане лише раз.", "work": "Множини допомагають швидко прибирати дублікати й перевіряти належність («чи є цей id уже оброблений»). Функції, що повертають кілька значень, насправді повертають кортеж.", "tasks": ["Прибрайте дублікати зі списку імен через множину.", "Знайдіть спільні елементи двох списків."]}, "dicts": {"t": "Словники", "p": ["Словник зберігає пари «ключ: значення» і дозволяє миттєво знаходити значення за ключем. Це основна структура для опису об'єктів: користувача, товару, налаштувань. Ключі зазвичай рядки, а значення можуть бути будь-якими, зокрема іншими словниками та списками.", "Звернення до відсутнього ключа через квадратні дужки викликає помилку, тому часто користуються методом <code>get</code> із запасним значенням. Для перебору служать <code>items()</code>, <code>keys()</code> і <code>values()</code>."], "code": ["user = {\"name\": \"Олена\", \"age\": 16, \"skills\": [\"python\", \"sql\"]}\n\nprint(user[\"name\"])\nprint(user.get(\"email\", \"немає\"))\nuser[\"email\"] = \"o@x.ua\"\ndel user[\"age\"]\n\nfor key, value in user.items():\n    print(key, \"->\", value)", "text = \"to be or not to be\"\ncounts = {}\nfor word in text.split():\n    counts[word] = counts.get(word, 0) + 1\nprint(counts)            # {'to': 2, 'be': 2, 'or': 1, 'not': 1}\n\nusers = [{\"name\": \"Анна\", \"age\": 20}, {\"name\": \"Тарас\", \"age\": 17}]\nadults = [u[\"name\"] for u in users if u[\"age\"] >= 18]\nprint(adults)"], "note": "Перевірити наявність ключа можна оператором <code>in</code>: <code>\"name\" in user</code>.", "easy": "Словник — це телефонна книга: за іменем (ключем) миттєво знаходиться номер (значення), не перебираючи всі записи.", "work": "Дані з API та файлів JSON у Python стають саме словниками й списками словників. Тож уміння дістати вкладене поле, безпечно звернутись через <code>get</code> і порахувати частоти — щоденна робота.", "tasks": ["Порахуйте, скільки разів кожна літера зустрічається в слові.", "Із списку словників виберіть імена тих, у кого вік більше 18."]}, "advfunc": {"t": "Параметри функцій, lambda та сортування", "p": ["Параметри можна передавати за позицією або за іменем: <code>greet(name=\"Олена\")</code>. Запис <code>*args</code> збирає довільну кількість позиційних аргументів у кортеж, а <code>**kwargs</code> — іменованих у словник. Опис функції пишуть у рядку-документації одразу під її оголошенням.", "Lambda — це коротка безіменна функція в один вираз. Її найчастіше передають як ключ у <code>sorted</code>, <code>min</code> та <code>max</code>."], "code": ["def total(*nums):\n    return sum(nums)\n\ndef show(**info):\n    for k, v in info.items():\n        print(k, \"=\", v)\n\ndef power(base, exp=2):\n    \"\"\"Піднімає число до степеня (за замовчуванням квадрат).\"\"\"\n    return base ** exp\n\nprint(total(1, 2, 3), power(3), power(exp=3, base=2))\nshow(name=\"Олена\", city=\"Дніпро\")", "products = [(\"Зошит\", 40), (\"Ручка\", 15), (\"Рюкзак\", 650)]\ncheap_first = sorted(products, key=lambda p: p[1])\nprint(cheap_first)\nprint(max(products, key=lambda p: p[1]))"], "note": "Не використовуйте змінний об'єкт як значення за замовчуванням (<code>def f(x=[])</code>): він створюється один раз і зберігається між викликами. Замість цього беріть <code>None</code>.", "easy": "*args — це відро для всіх зайвих аргументів, а lambda — записка з короткою командою, яку не треба оформлювати окремою функцією.", "work": "Параметр <code>key</code> у sorted і max зустрічається в кожному проєкті: сортувати список словників за полем — типова задача. Рядок-документацію пишуть до всіх публічних функцій, і IDE показує її у підказці.", "tasks": ["Відсортуйте список слів за довжиною.", "Напишіть функцію, що приймає довільну кількість чисел і повертає середнє."]}, "comp": {"t": "Генератори списків і корисні вбудовані функції", "p": ["Генератор списку створює новий список коротким записом: <code>[x * 2 for x in nums if x &gt; 0]</code>. Так само працюють генератори словників та множин. Це не лише коротше, а й читабельніше за цикл з додаванням в порожній список.", "Кілька вбудованих функцій допомагають писати лаконічний код: <code>enumerate</code> дає індекс і значення, <code>zip</code> поєднує кілька списків, <code>any</code> і <code>all</code> перевіряють умову для набору значень."], "code": ["nums = [3, -1, 4, -5, 9]\nsquares = [n * n for n in nums]\npositives = [n for n in nums if n > 0]\nprint(squares, positives)\n\nnames = [\"Анна\", \"Тарас\"]\nages = [20, 17]\nprint({n: a for n, a in zip(names, ages)})\n\nfor i, name in enumerate(names, start=1):\n    print(i, name)", "scores = [72, 85, 90, 64]\nprint(any(s >= 90 for s in scores))   # True\nprint(all(s >= 60 for s in scores))   # True\nprint(sum(scores) / len(scores), min(scores), max(scores))\nprint(sorted(scores, reverse=True)[:2])"], "note": "Якщо генератор списку займає більше двох рядків або містить вкладені умови, краще записати звичайним циклом: читабельність важливіша за стислість.", "easy": "Генератор списку — це конвеєр на фабриці: на вхід іде сирий список, на виході готовий, відфільтрований і перетворений.", "work": "Генератори списків, <code>zip</code> і <code>enumerate</code> — ознака «піфонівського» стилю, який очікують на код-рев'ю. Більшість перетворень даних у скриптах пишуть саме так.", "tasks": ["Створіть список довжин усіх слів у реченні.", "Поєднайте два списки у словник через zip."]}, "files": {"t": "Робота з файлами", "p": ["Файли відкривають функцією <code>open</code>. Режими: <code>\"r\"</code> — читання, <code>\"w\"</code> — запис (перезаписує файл), <code>\"a\"</code> — дописування. Завжди вказуйте <code>encoding=\"utf-8\"</code>, щоб українські літери не ламалися.", "Файл потрібно закривати. Найнадійніший спосіб — конструкція <code>with</code>: вона закриє файл автоматично, навіть якщо сталася помилка. Для шляхів зручний модуль <code>pathlib</code>."], "code": ["with open(\"notes.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"Перший рядок\\n\")\n    f.write(\"Другий рядок\\n\")\n\nwith open(\"notes.txt\", \"r\", encoding=\"utf-8\") as f:\n    for line in f:\n        print(line.strip())", "from pathlib import Path\n\npath = Path(\"data\") / \"log.txt\"\npath.parent.mkdir(exist_ok=True)\npath.write_text(\"Запуск програми\\n\", encoding=\"utf-8\")\nprint(path.exists(), path.read_text(encoding=\"utf-8\"))"], "note": "Режим <code>\"w\"</code> стирає наявний вміст файлу без попередження. Для дописування користуйтесь <code>\"a\"</code>.", "easy": "Конструкція with — як двері з доводчиком: файл сам закриється, що б не сталося всередині.", "work": "Скрипти постійно читають конфігурації, обробляють логи та зберігають результати. Помилки з кодуванням — одна з найчастіших проблем, тому <code>encoding=\"utf-8\"</code> пишуть завжди.", "tasks": ["Прочитайте файл і порахуйте кількість рядків.", "Запишіть у файл числа від 1 до 10, по одному в рядок."]}, "errors": {"t": "Помилки та винятки", "p": ["Коли щось іде не так, Python створює виняток і зупиняє програму. Блок <code>try / except</code> перехоплює виняток, щоб програма могла відреагувати. Ловіть конкретні винятки (<code>ValueError</code>, <code>FileNotFoundError</code>), а не всі підряд.", "Власний виняток створює оператор <code>raise</code>. Блок <code>finally</code> виконується завжди, а <code>else</code> — лише тоді, коли помилки не було."], "code": ["def to_age(text):\n    try:\n        age = int(text)\n    except ValueError:\n        print(\"Це не число:\", text)\n        return None\n    else:\n        if age < 0:\n            raise ValueError(\"Вік не може бути від'ємним\")\n        return age\n    finally:\n        print(\"Перевірку завершено\")\n\nprint(to_age(\"17\"))\nprint(to_age(\"abc\"))", "try:\n    with open(\"missing.txt\", encoding=\"utf-8\") as f:\n        print(f.read())\nexcept FileNotFoundError:\n    print(\"Файл не знайдено\")\n\n# Traceback читають знизу вгору: останній рядок — тип помилки, вище — де сталося"], "note": "Порожній <code>except:</code> без типу приховує всі помилки, зокрема справжні баги. Завжди вказуйте, що саме ловите.", "easy": "try/except — це страхувальна сітка циркача: якщо номер не вийшов, програма не розбивається, а ловить помилку.", "work": "Уміння читати traceback — головна навичка налагодження. Спершу дивіться на останній рядок (що сталося), потім піднімайтесь вгору до рядка свого коду (де сталося).", "tasks": ["Напишіть програму, що просить число й не падає, якщо ввели текст.", "Створіть функцію, що кидає ValueError для порожнього імені."]}, "modules": {"t": "Модулі, pip та віртуальне середовище", "p": ["Код розбивають на модулі: кожен файл <code>.py</code> можна підключити через <code>import</code>. Стандартна бібліотека Python вже містить десятки модулів (<code>math</code>, <code>random</code>, <code>datetime</code>). Умова <code>if __name__ == \"__main__\":</code> запускає код лише тоді, коли файл виконано напряму.", "Сторонні пакети встановлює утиліта <code>pip</code>. Для кожного проєкту створюють окреме віртуальне середовище, щоб бібліотеки різних проєктів не конфліктували, а список залежностей зберігають у <code>requirements.txt</code>."], "code": ["# utils.py\ndef square(x):\n    return x * x\n\nif __name__ == \"__main__\":\n    print(square(4))\n\n# main.py\nimport math\nimport random\nfrom datetime import date\nfrom utils import square\n\nprint(math.sqrt(16), random.randint(1, 6), date.today())\nprint(square(5))", "# термінал\npython -m venv .venv\n.venv\\Scripts\\activate        # Windows\nsource .venv/bin/activate     # macOS / Linux\n\npip install requests\npip freeze > requirements.txt\npip install -r requirements.txt"], "note": "Папку <code>.venv</code> не додають у Git. У репозиторії зберігають лише <code>requirements.txt</code>.", "easy": "Віртуальне середовище — це окрема шухляда інструментів для кожного проєкту, щоб бібліотеки не змішувались.", "work": "На першому ж робочому проєкті вам скажуть: «створи venv, встанови залежності з requirements.txt і запусти». Це базова послідовність, яку виконують щоразу на новому комп'ютері.", "tasks": ["Створіть venv, встановіть requests і збережіть requirements.txt.", "Винесіть дві функції в окремий модуль і підключіть його."]}, "jsoncsv": {"t": "Формати JSON і CSV", "p": ["JSON — найпоширеніший формат обміну даними. Модуль <code>json</code> перетворює словники й списки на текст (<code>dumps</code>, <code>dump</code>) і назад (<code>loads</code>, <code>load</code>). Для української мови додавайте <code>ensure_ascii=False</code>.", "CSV — це таблиця у вигляді тексту, де значення розділені комами. Модуль <code>csv</code> читає її у словники через <code>DictReader</code>, де ключі беруться з першого рядка."], "code": ["import json\n\nuser = {\"name\": \"Олена\", \"skills\": [\"python\", \"sql\"]}\ntext = json.dumps(user, ensure_ascii=False, indent=2)\nprint(text)\n\nwith open(\"user.json\", \"w\", encoding=\"utf-8\") as f:\n    json.dump(user, f, ensure_ascii=False, indent=2)\n\nwith open(\"user.json\", encoding=\"utf-8\") as f:\n    data = json.load(f)\nprint(data[\"skills\"])", "import csv\n\n# students.csv: name,grade\n#                Анна,95\n#                Тарас,80\nwith open(\"students.csv\", encoding=\"utf-8\", newline=\"\") as f:\n    rows = list(csv.DictReader(f))\n\nbest = max(rows, key=lambda r: int(r[\"grade\"]))\nprint(best[\"name\"])"], "note": "Усі значення з CSV приходять як рядки, тому числа потрібно перетворювати через <code>int()</code> або <code>float()</code>.", "easy": "JSON — це посилка зі словниками й списками всередині, CSV — таблиця Excel, записана простим текстом.", "work": "Обробка файлів CSV і JSON — типова задача для автоматизації: вивантаження з бази, звіти, імпорт даних. Після такого скрипта на Python вручну в Excel вже ніхто нічого не копіює.", "tasks": ["Збережіть список словників у файл JSON і прочитайте його назад.", "Прочитайте CSV і порахуйте середнє значення числового стовпця."]}, "classes": {"t": "Класи та об'єкти", "p": ["Клас — це шаблон, за яким створюють об'єкти. Метод <code>__init__</code> викликається під час створення об'єкта й задає його початкові дані, а перший параметр методів <code>self</code> — це сам об'єкт. Метод <code>__str__</code> визначає, як об'єкт виглядає під час виведення.", "Для простих класів з даними існує декоратор <code>@dataclass</code>: він автоматично створює <code>__init__</code>, виведення й порівняння."], "code": ["class Account:\n    def __init__(self, owner, balance=0):\n        self.owner = owner\n        self.balance = balance\n\n    def deposit(self, amount):\n        if amount <= 0:\n            raise ValueError(\"Сума має бути додатною\")\n        self.balance += amount\n\n    def __str__(self):\n        return f\"{self.owner}: {self.balance} грн\"\n\nacc = Account(\"Олена\", 100)\nacc.deposit(50)\nprint(acc)", "from dataclasses import dataclass\n\n@dataclass\nclass Product:\n    name: str\n    price: float\n    in_stock: bool = True\n\np = Product(\"Зошит\", 40)\nprint(p)\nprint(p.price * 3)"], "note": "Поле з одним підкресленням (<code>_balance</code>) за домовленістю вважається внутрішнім: ззовні його краще не чіпати.", "easy": "Клас — це креслення, а об'єкт — конкретна річ, зроблена за ним. self означає «саме ця річ».", "work": "У реальних проєктах моделі даних (користувач, замовлення, товар) описують класами або dataclass. Фреймворки Django та FastAPI ґрунтуються саме на цьому підході.", "tasks": ["Створіть клас Rectangle з методом площі.", "Опишіть dataclass Student з іменем, групою та оцінкою."]}, "inherit": {"t": "Наслідування та property", "p": ["Клас-нащадок успадковує поля й методи батьківського класу та може їх перевизначати. Виклик батьківської логіки робить <code>super()</code>. Завдяки цьому різні класи можна використовувати однаково: це називають поліморфізмом.", "Декоратор <code>@property</code> дозволяє звертатися до методу як до поля. Це зручно для обчислюваних значень і перевірок."], "code": ["class Shape:\n    def area(self):\n        raise NotImplementedError\n\nclass Rectangle(Shape):\n    def __init__(self, w, h):\n        self.w, self.h = w, h\n    def area(self):\n        return self.w * self.h\n\nclass Circle(Shape):\n    def __init__(self, r):\n        self.r = r\n    def area(self):\n        return 3.14159 * self.r ** 2\n\nfor s in [Rectangle(2, 3), Circle(1)]:\n    print(type(s).__name__, round(s.area(), 2))", "class Temperature:\n    def __init__(self, celsius):\n        self.celsius = celsius\n\n    @property\n    def fahrenheit(self):\n        return self.celsius * 9 / 5 + 32\n\nt = Temperature(25)\nprint(t.fahrenheit)   # 77.0 — без дужок"], "note": "Успадковуйте тоді, коли клас справді «є різновидом» батьківського. Якщо він лише «використовує» інший, краще зберегти його як поле.", "easy": "Наслідування — це родинна схожість: нащадок отримує риси батька і може додати або змінити свої.", "work": "У великих проєктах глибокі ієрархії наслідування не люблять: їх складно читати. Частіше користуються простими базовими класами та композицією, а <code>@property</code> — для зручного доступу до даних.", "tasks": ["Створіть базовий клас Animal і двох нащадків із різним методом speak.", "Додайте клас Square як нащадок Rectangle."]}, "requests": {"t": "Запити до API з бібліотекою requests", "p": ["Бібліотека <code>requests</code> робить HTTP-запити простими. Метод <code>get</code> отримує дані, <code>post</code> надсилає їх. Об'єкт відповіді має <code>status_code</code>, <code>text</code> та метод <code>json()</code>, який повертає словник чи список.", "Завжди задавайте <code>timeout</code>, щоб програма не чекала нескінченно, і перевіряйте відповідь методом <code>raise_for_status()</code>: він викличе помилку для статусів 4xx та 5xx."], "code": ["import requests\n\nAPI = \"https://jsonplaceholder.typicode.com\"\n\ntry:\n    r = requests.get(API + \"/posts\", params={\"_limit\": 3}, timeout=10)\n    r.raise_for_status()\n    for post in r.json():\n        print(post[\"id\"], post[\"title\"])\nexcept requests.RequestException as e:\n    print(\"Помилка запиту:\", e)", "payload = {\"title\": \"Привіт\", \"body\": \"Мій пост\", \"userId\": 1}\nr = requests.post(API + \"/posts\", json=payload, timeout=10)\nprint(r.status_code)     # 201\nprint(r.json()[\"id\"])"], "note": "Бібліотеку потрібно встановити: <code>pip install requests</code>. Робіть це у віртуальному середовищі.", "easy": "API — це меню сервера: ви замовляєте дані запитом, а requests доставляє замовлення й приносить відповідь.", "work": "Скрипти для збору даних, інтеграції із зовнішніми сервісами й автоматизація звітів майже завжди починаються з requests. Ключі API не вписують у код, а беруть із змінних середовища.", "tasks": ["Отримайте список користувачів із jsonplaceholder і виведіть їхні email.", "Надішліть POST-запит і виведіть статус відповіді."]}, "pytest": {"t": "Тестування з pytest", "p": ["Тест — це код, що перевіряє, чи працює інший код. Бібліотека <code>pytest</code> шукає файли <code>test_*.py</code>, запускає функції, назви яких починаються з <code>test_</code>, і перевіряє умови через звичайний <code>assert</code>.", "Декоратор <code>@pytest.mark.parametrize</code> дозволяє прогнати один тест на багатьох наборах даних, а <code>pytest.raises</code> перевіряє, що функція справді кидає очікувану помилку."], "code": ["# calc.py\ndef divide(a, b):\n    if b == 0:\n        raise ValueError(\"Ділення на нуль\")\n    return a / b\n\n# test_calc.py\nimport pytest\nfrom calc import divide\n\ndef test_divide():\n    assert divide(10, 2) == 5\n\n@pytest.mark.parametrize(\"a, b, expected\", [(9, 3, 3), (1, 2, 0.5), (0, 5, 0)])\ndef test_many(a, b, expected):\n    assert divide(a, b) == expected\n\ndef test_zero():\n    with pytest.raises(ValueError):\n        divide(1, 0)", "# термінал\npip install pytest\npytest\npytest -v"], "note": "Назва тесту має описувати поведінку, яку перевіряють. За повідомленням про падіння має бути зрозуміло, що саме зламалося.", "easy": "Тести — це контрольний список перед польотом: щоразу, коли ви змінюєте код, вони швидко перевіряють, що старе не зламалось.", "work": "У командах код без тестів часто просто не приймають. Навіть кілька простих тестів на ключові функції показують, що ви вмієте працювати за практиками, прийнятими в індустрії.", "tasks": ["Напишіть три тести для функції, що перевіряє, чи число парне.", "Додайте parametrize для різних вхідних значень."]}};
  const easyOld = {"Перша програма: print і коментарі": "print — це голос програми: усе, що ви в нього передасте, з'явиться на екрані. Коментар — нотатка на полях для людей.", "Змінні та типи даних": "Змінна — це підписана коробка, у яку кладуть значення. Тип — це підказка, що в коробці: число, текст чи так/ні.", "Ввід даних і розгалуження": "input — це питання користувачу, а if — розвилка: програма вибирає шлях залежно від відповіді.", "Цикли for і while": "Цикл — це команда «повторюй». for повторює задану кількість разів, while — доки умова правдива.", "Рядки": "Рядок — це текст, складений з символів у ряд. До кожного можна звернутись за номером, а методи виконують готові дії.", "Списки": "Список — це нумерований перелік, до якого можна додавати, видаляти й змінювати пункти.", "Функції": "Функція — це рецепт: записали кроки раз і викликаємо скільки завгодно, змінюючи інгредієнти."};
  const workOld = {"Перша програма: print і коментарі": "У робочому коді print використовують переважно для швидкої перевірки. Для серйозних програм застосовують модуль logging, а коментарі пишуть про «навіщо», а не «що».", "Змінні та типи даних": "Імена змінних у Python пишуть англійською у стилі snake_case (<code>user_name</code>, <code>total_price</code>). Це частина стандарту PEP 8, якого дотримуються всі команди.", "Ввід даних і розгалуження": "Дані, які вводить користувач, завжди перевіряють: програма не має падати від порожнього рядка чи літер замість числа. Далі ви навчитесь робити це через винятки.", "Цикли for і while": "Цикли використовують для обробки списків записів, файлів і відповідей API. Індекси <code>range(len(x))</code> у Python вважаються поганим стилем: перебирають самі елементи.", "Рядки": "Форматування f-рядками — стандарт сучасного Python. Обробка тексту (очищення, розбиття, пошук) — це велика частина реальних скриптів.", "Списки": "Списки з даними — основа більшості скриптів: рядки з файлу, відповіді API, результати запитів до бази. Операції над ними вчать виконувати швидко й без помилок.", "Функції": "Функції — головний спосіб навести лад у коді. Правило: одна функція — одна задача й зрозуміла назва, а довгий скрипт розбивають на кілька коротких."};
  const byTitle = {};
  LESSONS.python.forEach(l => { byTitle[l.t] = l; l.easy = easyOld[l.t]; l.work = workOld[l.t]; });
  const T = t => { if (!byTitle[t]) throw new Error("Немає уроку: " + t); return byTitle[t]; };
  LESSONS.python = [N.install, T("Перша програма: print і коментарі"), T("Змінні та типи даних"), T("Ввід даних і розгалуження"), T("Цикли for і while"),
    T("Рядки"), T("Списки"), N.tuples, N.dicts, T("Функції"), N.advfunc, N.comp,
    N.files, N.errors, N.modules, N.jsoncsv, N.classes, N.inherit, N.requests, N.pytest];
  CHAPTERS.python = [["Початок", 0], ["Основи мови", 2], ["Структури даних", 5], ["Функції", 9], ["Файли, помилки, пакети", 12], ["Класи", 16], ["Практика", 18]];
  CHAPTERS.python.forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS.python.length;
    for (let j = from; j < to; j++) LESSONS.python[j].ch = name;
  });
})();

/* ===== SQL: 15 уроків ===== */
(function () {
  const N = {"start": {"t": "Бази даних і SQL: де практикуватись", "p": ["База даних — це організоване сховище інформації, а SQL — мова, якою до нього звертаються. Дані лежать у таблицях: стовпчики задають поля, а кожен рядок — один запис. Найпопулярніші системи — PostgreSQL, MySQL і SQLite; основи SQL в них однакові.", "Для навчання зручна SQLite: вона не потребує сервера. Скористайтесь онлайн-редактором (наприклад, sqliteonline.com) або консоллю <code>sqlite3</code>. Виконайте скрипт нижче один раз: усі приклади курсу використовують ці таблиці."], "code": ["CREATE TABLE courses (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL\n);\nCREATE TABLE students (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  grade INTEGER,\n  course_id INTEGER REFERENCES courses(id)\n);\n\nINSERT INTO courses VALUES (1, 'Python'), (2, 'JavaScript'), (3, 'SQL');\nINSERT INTO students VALUES\n  (1, 'Олена',  'Дніпро', 11, 1),\n  (2, 'Артем',  'Київ',    9, 2),\n  (3, 'Оксана', 'Дніпро', 12, 1),\n  (4, 'Тарас',  'Львів',   8, 3),\n  (5, 'Анна',   'Київ',   10, 2),\n  (6, 'Іван',   'Дніпро', NULL, NULL);\n\nSELECT * FROM students;"], "note": "SQL нечутливий до регістру ключових слів, але прийнято писати їх великими літерами, а команди завершувати крапкою з комою.", "easy": "База даних — це шафа з картотеками, таблиця — одна шухляда, а рядок — одна картка. SQL — спосіб попросити картотекаря знайти потрібні картки.", "work": "У роботі ви звертатиметесь до справжньої бази (найчастіше PostgreSQL або MySQL) через клієнт на кшталт DBeaver. Синтаксис базових запитів однаковий, а відмінності (функції дат, типи) завжди можна подивитись у документації.", "tasks": ["Виконайте скрипт і перегляньте вміст обох таблиць.", "Порахуйте на око, скільки учнів у таблиці students."]}, "cond": {"t": "Умови: IN, BETWEEN, LIKE та NULL", "p": ["Окрім порівнянь, у <code>WHERE</code> є зручні оператори: <code>IN</code> перевіряє належність до списку, <code>BETWEEN</code> — діапазон, <code>LIKE</code> — збіг із шаблоном (<code>%</code> — будь-які символи, <code>_</code> — один символ).", "Значення <code>NULL</code> означає «невідомо» і порівнюється особливим чином: умова <code>grade = NULL</code> ніколи не спрацює. Перевіряти потрібно через <code>IS NULL</code> або <code>IS NOT NULL</code>."], "code": ["SELECT * FROM students WHERE city IN ('Дніпро', 'Львів');\nSELECT * FROM students WHERE grade BETWEEN 9 AND 11;\nSELECT * FROM students WHERE name LIKE 'О%';\nSELECT * FROM students WHERE name LIKE '%а';\n\nSELECT * FROM students WHERE grade IS NULL;\nSELECT * FROM students WHERE NOT city = 'Київ';"], "note": "Порівняння з NULL через <code>=</code> — одна з найчастіших помилок початківців. Запам'ятайте: лише <code>IS NULL</code>.", "easy": "NULL — це порожня клітинка анкети: «не заповнено». Порівняти її з чимось безглуздо, можна лише спитати, чи вона порожня.", "work": "Реальні дані завжди містять порожні значення, тому перевірка на NULL трапляється в запитах постійно. Також уважно пишіть дужки в умовах з AND та OR: без них результат часто відрізняється від очікуваного.", "tasks": ["Виберіть учнів, чиє місто не вказано або оцінка відсутня.", "Знайдіть усіх, у кого ім'я починається на «А» або «О»."]}, "funcs": {"t": "Функції та вирази: CASE, COALESCE, рядки", "p": ["SQL уміє виконувати обчислення прямо в запиті. Рядкові функції: <code>UPPER</code>, <code>LOWER</code>, <code>LENGTH</code>, <code>SUBSTR</code>, склеювання через <code>||</code>. Псевдонім <code>AS</code> дає стовпчику зручну назву.", "Вираз <code>CASE</code> працює як умова в запиті, а <code>COALESCE</code> підставляє запасне значення замість NULL."], "code": ["SELECT name,\n       UPPER(city) AS city_up,\n       LENGTH(name) AS name_len,\n       name || ' (' || city || ')' AS label\nFROM students;\n\nSELECT name,\n       COALESCE(grade, 0) AS grade_safe,\n       CASE\n         WHEN grade >= 11 THEN 'відмінно'\n         WHEN grade >= 8  THEN 'добре'\n         ELSE 'немає даних'\n       END AS level\nFROM students;"], "note": "Функції дат відрізняються між СУБД: у SQLite це <code>date('now')</code>, у PostgreSQL — <code>CURRENT_DATE</code>. Дивіться документацію вашої бази.", "easy": "CASE — це розвилка прямо всередині запиту: «якщо так, то це, а якщо ні — інше».", "work": "Звіти часто потребують обчислюваних стовпчиків: статус замовлення словами, знижка за умовою, повне ім'я. Їх зручніше рахувати в запиті, ніж у коді застосунку.", "tasks": ["Виведіть імена великими літерами і довжину кожного імені.", "За допомогою CASE розбийте учнів на «вище 10» та «10 і нижче»."]}, "agg": {"t": "Агрегатні функції та GROUP BY", "p": ["Агрегатні функції рахують один підсумок за багатьма рядками: <code>COUNT</code>, <code>SUM</code>, <code>AVG</code>, <code>MIN</code>, <code>MAX</code>. Вони ігнорують NULL, окрім <code>COUNT(*)</code>.", "<code>GROUP BY</code> ділить рядки на групи й рахує підсумок для кожної. Умову на результат групи пишуть у <code>HAVING</code>, а умову на окремі рядки — у <code>WHERE</code>."], "code": ["SELECT COUNT(*) AS total, AVG(grade) AS avg_grade, MAX(grade) AS best\nFROM students;\n\nSELECT city, COUNT(*) AS students, AVG(grade) AS avg_grade\nFROM students\nWHERE grade IS NOT NULL\nGROUP BY city\nHAVING COUNT(*) >= 2\nORDER BY avg_grade DESC;"], "note": "Кожен стовпчик у SELECT має або входити в GROUP BY, або бути агрегатною функцією. Інакше запит повертає помилку або неоднозначний результат.", "easy": "GROUP BY — це розкласти картки по стосах за містом і порахувати окремо кожен стос.", "work": "Звіти й дашборди — це здебільшого агрегати: кількість замовлень за день, середній чек за місяць, виручка за категорією. Вміння швидко скласти такий запит високо цінується.", "tasks": ["Порахуйте, скільки учнів у кожному місті.", "Виведіть міста, де середня оцінка вища за 10."]}, "create": {"t": "Створення таблиць: CREATE TABLE та типи даних", "p": ["Таблицю створюють командою <code>CREATE TABLE</code>, вказуючи стовпчики й їхні типи: <code>INTEGER</code>, <code>REAL</code>, <code>TEXT</code>, <code>DATE</code> і так далі. Обмеження захищають дані: <code>PRIMARY KEY</code> (унікальний ідентифікатор), <code>NOT NULL</code>, <code>UNIQUE</code>, <code>DEFAULT</code>, <code>CHECK</code>.", "Змінити готову таблицю можна через <code>ALTER TABLE</code>, а видалити — через <code>DROP TABLE</code> (остання дія незворотна)."], "code": ["CREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  price REAL NOT NULL CHECK (price >= 0),\n  sku TEXT UNIQUE,\n  in_stock INTEGER DEFAULT 1\n);\n\nALTER TABLE products ADD COLUMN description TEXT;\nDROP TABLE IF EXISTS temp_data;"], "note": "Команда <code>DROP TABLE</code> без резервної копії видаляє дані назавжди. У робочій базі її виконують дуже обережно.", "easy": "Обмеження — це правила на вході до таблиці: охоронець, який не пропустить рядок з порожнім обов'язковим полем чи від'ємною ціною.", "work": "Структуру бази в командах змінюють через міграції — файли зі скриптами, які зберігаються в Git. Прямо в робочій базі таблиці вручну не створюють.", "tasks": ["Створіть таблицю orders з id, датою, сумою та статусом із значенням за замовчуванням.", "Додайте до неї стовпчик comment через ALTER TABLE."]}, "dml": {"t": "Зміна даних: INSERT, UPDATE, DELETE", "p": ["Рядки додають командою <code>INSERT INTO</code>, змінюють — <code>UPDATE</code>, видаляють — <code>DELETE</code>. Для двох останніх обов'язково потрібен <code>WHERE</code>.", "Забули WHERE — зміна чи видалення торкнеться кожного рядка таблиці. Тому перед змінами спершу запускають такий самий запит із <code>SELECT</code>, щоб побачити, які рядки потраплять під дію."], "code": ["INSERT INTO products (title, price) VALUES ('Зошит', 40);\nINSERT INTO products (title, price, sku) VALUES\n  ('Ручка', 15, 'PEN-1'),\n  ('Рюкзак', 650, 'BAG-7');\n\nSELECT * FROM products WHERE title = 'Ручка';   -- спершу перевіряємо\nUPDATE products SET price = 18 WHERE title = 'Ручка';\n\nDELETE FROM products WHERE price < 20;"], "note": "Команди UPDATE і DELETE без WHERE чіпають усі рядки. Це найвідоміша помилка, що призводила до втрати даних у компаніях.", "easy": "UPDATE і DELETE — це маркер і гумка: WHERE вказує, де саме писати чи стирати. Без нього гумка пройдеться по всьому аркушу.", "work": "Перед будь-якою зміною даних на робочій базі розробники перевіряють запит через SELECT і виконують зміни в транзакції, яку можна скасувати. Про транзакції ми поговоримо в одному з наступних уроків.", "tasks": ["Додайте три товари і підніміть ціну одного з них.", "Видаліть один товар за його id."]}, "rel": {"t": "Зв'язки між таблицями та FOREIGN KEY", "p": ["Дані розділяють по таблицях, щоб не дублювати інформацію. Замість назви курсу в кожному рядку учня зберігають <code>course_id</code>, який посилається на таблицю курсів. Таке посилання називають зовнішнім ключем (<code>FOREIGN KEY</code>).", "Є три типи зв'язків: «один до багатьох» (курс — учні), «багато до багатьох» (учні — гуртки, через проміжну таблицю) та «один до одного». Розділення даних на таблиці називають нормалізацією."], "code": ["CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL,\n  total REAL NOT NULL,\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\n);\n\n-- зв'язок «багато до багатьох»: учні та гуртки\nCREATE TABLE enrollments (\n  student_id INTEGER REFERENCES students(id),\n  club_id    INTEGER,\n  PRIMARY KEY (student_id, club_id)\n);"], "note": "У SQLite перевірку зовнішніх ключів вмикають командою <code>PRAGMA foreign_keys = ON;</code>, а в PostgreSQL та MySQL вона працює за замовчуванням.", "easy": "Зовнішній ключ — це посилання «дивись картку №5 в іншій шухляді». Так дані не дублюються, а зв'язок лишається надійним.", "work": "Проєктування таблиць і зв'язків — те, що відрізняє розробника, який «вміє писати запити», від того, хто може спроєктувати базу для застосунку. Починайте з малюнка: які сутності є і як вони пов'язані.", "tasks": ["Спроєктуйте таблиці для блогу: користувачі, пости, коментарі. Визначте зовнішні ключі.", "Опишіть проміжну таблицю для зв'язку «товари та замовлення»."]}, "join": {"t": "JOIN: об'єднання таблиць", "p": ["<code>JOIN</code> з'єднує рядки двох таблиць за спільним значенням. <code>INNER JOIN</code> залишає лише ті рядки, для яких знайшлася пара. <code>LEFT JOIN</code> залишає всі рядки лівої таблиці, а де пари немає, підставляє NULL.", "Таблицям у запиті дають короткі псевдоніми, а перед назвою стовпчика вказують таблицю, щоб уникнути неоднозначності: <code>s.name</code>, <code>c.title</code>."], "code": ["SELECT s.name, c.title\nFROM students s\nINNER JOIN courses c ON c.id = s.course_id;\n\n-- Іван без курсу теж потрапляє до результату\nSELECT s.name, c.title\nFROM students s\nLEFT JOIN courses c ON c.id = s.course_id;\n\nSELECT c.title, COUNT(s.id) AS students\nFROM courses c\nLEFT JOIN students s ON s.course_id = c.id\nGROUP BY c.title;"], "note": "Щоб знайти рядки без пари, використовують LEFT JOIN з умовою <code>WHERE c.id IS NULL</code>.", "easy": "INNER JOIN — це лише ті, у кого є пара. LEFT JOIN — це всі з лівого списку, а пара є не в усіх.", "work": "JOIN — найвживаніша конструкція в запитах до реальних баз: майже жодна цікава вибірка не обходиться без двох-трьох таблиць. Це також улюблена тема тестових завдань.", "tasks": ["Виведіть імена учнів з назвами їхніх курсів.", "Знайдіть учнів, які не записані на жоден курс."]}, "sub": {"t": "Підзапити та CTE", "p": ["Підзапит — це запит усередині іншого запиту. Його можна використати в <code>WHERE</code> (порівняти з обчисленим значенням), у <code>FROM</code> (як тимчасову таблицю) або в <code>SELECT</code>. Оператор <code>EXISTS</code> перевіряє, чи є хоч один рядок у підзапиті.", "CTE (вираз <code>WITH</code>) дає підзапиту ім'я й виносить його нагору. Складний запит стає схожим на послідовність кроків, яку легше читати."], "code": ["SELECT name, grade FROM students\nWHERE grade > (SELECT AVG(grade) FROM students);\n\nSELECT title FROM courses c\nWHERE EXISTS (SELECT 1 FROM students s WHERE s.course_id = c.id);\n\nWITH city_stats AS (\n  SELECT city, AVG(grade) AS avg_grade\n  FROM students\n  WHERE grade IS NOT NULL\n  GROUP BY city\n)\nSELECT s.name, s.city, s.grade, cs.avg_grade\nFROM students s\nJOIN city_stats cs ON cs.city = s.city\nWHERE s.grade > cs.avg_grade;"], "note": "Підзапит у WHERE, що повертає кілька значень, порівнюють через <code>IN</code>, а не через <code>=</code>.", "easy": "Підзапит — це запитання всередині запитання: «знайди тих, у кого оцінка вища за середню» спершу вимагає порахувати середню.", "work": "Складні звіти пишуть через CTE: так запит читається зверху вниз, а колеги легко знаходять помилку. Довгі вкладені підзапити на код-рев'ю зазвичай просять переписати.", "tasks": ["Знайдіть учнів з оцінкою вищою за середню по всій таблиці.", "Перепишіть цей запит через CTE."]}, "window": {"t": "Віконні функції", "p": ["Віконні функції рахують значення для кожного рядка, не склеюючи рядки в групи. Це відрізняє їх від <code>GROUP BY</code>. Синтаксис: функція, потім <code>OVER (PARTITION BY ... ORDER BY ...)</code>.", "Популярні функції: <code>ROW_NUMBER</code> нумерує рядки, <code>RANK</code> дає місце з урахуванням рівних, а звичайні <code>SUM</code>, <code>AVG</code> з <code>OVER</code> рахують накопичувальні та групові підсумки."], "code": ["SELECT name, city, grade,\n       RANK() OVER (ORDER BY grade DESC) AS place,\n       ROW_NUMBER() OVER (PARTITION BY city ORDER BY grade DESC) AS in_city,\n       AVG(grade) OVER (PARTITION BY city) AS city_avg\nFROM students\nWHERE grade IS NOT NULL;\n\n-- найкращий учень у кожному місті\nWITH ranked AS (\n  SELECT name, city, grade,\n         ROW_NUMBER() OVER (PARTITION BY city ORDER BY grade DESC) AS rn\n  FROM students WHERE grade IS NOT NULL\n)\nSELECT name, city, grade FROM ranked WHERE rn = 1;"], "note": "Віконні функції не можна використовувати прямо в <code>WHERE</code>. Спершу їх обчислюють у підзапиті чи CTE, а потім фільтрують.", "easy": "GROUP BY склеює стос карток у одну. Віконна функція лишає всі картки на місці й дописує на кожній додаткову цифру.", "work": "Рейтинги, «топ-3 у кожній категорії», зростаючий підсумок продажів — задачі для віконних функцій. Їх часто дають на технічних інтерв'ю, бо вони показують рівень вище початкового.", "tasks": ["Пронумеруйте учнів у кожному місті за оцінкою.", "Знайдіть двох найкращих учнів кожного міста."]}, "index": {"t": "Індекси та швидкість запитів", "p": ["Без індексу база для пошуку проходить усі рядки таблиці. Індекс працює як зміст книги: за ним значення знаходять швидко. Його створюють на стовпчики, за якими часто шукають, фільтрують або з'єднують таблиці.", "Індекс прискорює читання, але сповільнює запис і займає місце, тому їх не додають на кожен стовпчик. Подивитись, як база виконує запит, можна командою <code>EXPLAIN</code>."], "code": ["CREATE INDEX idx_students_city ON students(city);\nCREATE UNIQUE INDEX idx_products_sku ON products(sku);\n\nEXPLAIN QUERY PLAN\nSELECT * FROM students WHERE city = 'Дніпро';\n-- у плані має бути: SEARCH ... USING INDEX idx_students_city\n\nDROP INDEX idx_students_city;"], "note": "Запит <code>SELECT *</code> витягує всі стовпчики. На великих таблицях вибирайте лише потрібні поля: це швидше.", "easy": "Індекс — це алфавітний покажчик у кінці книги: замість читання всіх сторінок ви одразу відкриваєте потрібну.", "work": "Повільний запит — типова проблема, яку розв'язують на роботі. Перший крок завжди однаковий: запустити EXPLAIN, побачити, чи база перебирає всю таблицю, і додати індекс на стовпчик з умови чи JOIN.", "tasks": ["Створіть індекс на стовпчик, за яким ви часто шукаєте, і перевірте план запиту.", "Поясніть, чому не варто робити індекс на кожен стовпчик."]}, "trans": {"t": "Транзакції", "p": ["Транзакція — це група команд, що виконується як одне ціле: або всі зміни застосовуються, або жодна. Класичний приклад — переказ грошей: зняття з одного рахунку й зарахування на інший мають відбутися разом.", "Транзакцію відкриває <code>BEGIN</code>, підтверджує <code>COMMIT</code>, а скасовує <code>ROLLBACK</code>. Властивості надійної транзакції позначають абревіатурою ACID: атомарність, узгодженість, ізольованість, довговічність."], "code": ["BEGIN;\n\nUPDATE accounts SET balance = balance - 100 WHERE id = 1;\nUPDATE accounts SET balance = balance + 100 WHERE id = 2;\n\n-- якщо все гаразд:\nCOMMIT;\n-- якщо щось пішло не так:\n-- ROLLBACK;"], "note": "Якщо між двома командами переказу станеться збій, без транзакції гроші зникнуть. Тому всі зв'язані зміни завжди об'єднують.", "easy": "Транзакція — це «все або нічого»: або обидві операції переказу виконані, або база повертається до початкового стану.", "work": "Будь-які зміни, що зачіпають кілька таблиць (оформлення замовлення, списання зі складу, оплата), у робочих застосунках виконують у транзакції. Про це часто запитують на співбесідах.", "tasks": ["Напишіть транзакцію, що переносить товар зі складу A на склад B.", "Поясніть своїми словами, що таке атомарність."]}, "pysql": {"t": "SQL у програмі: Python і sqlite3", "p": ["У реальних застосунках SQL-запити виконує код. Python має вбудований модуль <code>sqlite3</code>: він підключається до файлу бази, виконує запити й повертає результат. Зміни потрібно підтвердити викликом <code>commit()</code>.", "Значення у запит ніколи не підставляють склеюванням рядків. Використовують параметри <code>?</code>: це єдиний надійний захист від SQL-ін'єкцій."], "code": ["import sqlite3\n\nconn = sqlite3.connect(\"school.db\")\nconn.row_factory = sqlite3.Row\ncur = conn.cursor()\n\ncity = \"Дніпро\"\ncur.execute(\"SELECT name, grade FROM students WHERE city = ?\", (city,))\nfor row in cur.fetchall():\n    print(row[\"name\"], row[\"grade\"])\n\ncur.execute(\"INSERT INTO students (name, city, grade) VALUES (?, ?, ?)\",\n            (\"Марія\", \"Одеса\", 10))\nconn.commit()\nconn.close()", "# НЕБЕЗПЕЧНО: ніколи так не пишіть\n# cur.execute(\"SELECT * FROM students WHERE city = '\" + user_input + \"'\")\n# Якщо user_input = \"x' OR '1'='1\", запит поверне всю таблицю"], "note": "Підставляти у запит назви таблиць чи стовпчиків через параметри не можна, лише значення. Назви перевіряють за списком дозволених.", "easy": "Параметри ? — це окремі конверти для значень: що б у конверті не лежало, база сприйме це лише як дані, а не як команду.", "work": "SQL-ін'єкція — одна з найпоширеніших вразливостей, і параметризовані запити вважаються базовою вимогою. У проєктах зазвичай використовують ORM (SQLAlchemy, Django ORM), але знання чистого SQL допомагає розуміти, що ORM робить за вас.", "tasks": ["Напишіть функцію, що отримує учнів за містом із параметризованим запитом.", "Додайте нового учня і виведіть їх усіх."]}};
  const easyOld = {"Вибірка даних: SELECT": "SELECT — це прохання «покажи мені такі-то стовпчики з такої-то таблиці». Зірочка означає «усі».", "Фільтрація й сортування": "WHERE працює як фільтр у інтернет-магазині: залишає лише потрібні рядки. ORDER BY розставляє їх у потрібному порядку."};
  const workOld = {"Вибірка даних: SELECT": "У реальних проєктах таблиці мають сотні стовпчиків і мільйони рядків, тому <code>SELECT *</code> зазвичай замінюють на список потрібних полів і додають <code>LIMIT</code> для перегляду.", "Фільтрація й сортування": "Фільтрація та сортування лежать в основі кожної сторінки з таблицею даних: пошук, фільтри за датою чи категорією, постраничний вивід через <code>LIMIT</code> та <code>OFFSET</code>."};
  const byTitle = {};
  LESSONS.sql.forEach(l => { byTitle[l.t] = l; l.easy = easyOld[l.t]; l.work = workOld[l.t]; });
  const sel = byTitle["Вибірка даних: SELECT"];
  sel.tasks = ["Виберіть лише імена та міста всіх учнів.", "Отримайте список унікальних міст."];
  byTitle["Фільтрація й сортування"].tasks = ["Виберіть трьох учнів із найвищими оцінками.", "Знайдіть усіх, чиє ім'я закінчується на «а»."];
  LESSONS.sql = [N.start, sel, byTitle["Фільтрація й сортування"], N.cond, N.funcs, N.agg,
    N.create, N.dml, N.rel, N.join, N.sub, N.window, N.index, N.trans, N.pysql];
  CHAPTERS.sql = [["Початок", 0], ["Вибірка даних", 1], ["Структура та зміна даних", 6], ["Складні запити", 9], ["Продуктивність і практика", 12]];
  CHAPTERS.sql.forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS.sql.length;
    for (let j = from; j < to; j++) LESSONS.sql[j].ch = name;
  });
})();

/* ===== HTML ===== */
(function () {
  const N = {"tools": {"t": "Інструменти веброзробника", "p": ["Для роботи з HTML потрібні лише дві речі: редактор коду та браузер. Встановіть Visual Studio Code, а до нього розширення <b>Live Server</b>: воно відкриває сторінку в браузері й оновлює її після кожного збереження.", "Усі сучасні браузери мають інструменти розробника (клавіша F12). У вкладці <code>Elements</code> видно структуру сторінки, а вибравши елемент, можна подивитись його стилі й одразу спробувати їх змінити."], "code": ["<!-- index.html: збережіть файл і запустіть Live Server -->\n<!DOCTYPE html>\n<html lang=\"uk\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Перша сторінка</title>\n</head>\n<body>\n  <h1>Все працює!</h1>\n</body>\n</html>"], "note": "Файли називайте латиницею, без пробілів і великих літер: <code>index.html</code>, <code>about-us.html</code>. Головна сторінка сайту завжди називається <code>index.html</code>.", "easy": "HTML — це скелет сторінки, а браузер — будівельник, який за цим скелетом збирає те, що ви бачите. DevTools — рентген, що показує цей скелет.", "work": "Веброзробник відкриває DevTools постійно: перевірити, чому елемент не там, подивитись запити, знайти помилку. Навчіться швидко знаходити елемент на сторінці та читати його стилі.", "tasks": ["Встановіть VS Code і Live Server та запустіть свою першу сторінку.", "Відкрийте будь-який сайт, натисніть F12 і знайдіть у Elements його головний заголовок."]}, "text": {"t": "Форматування тексту", "p": ["HTML має теги, що передають зміст, а не лише вигляд. <code>&lt;strong&gt;</code> позначає важливий текст, <code>&lt;em&gt;</code> — наголос, <code>&lt;mark&gt;</code> — виділення, <code>&lt;code&gt;</code> — фрагмент коду, <code>&lt;blockquote&gt;</code> — цитату.", "Багаторядковий код і текст із збереженням пробілів розміщують у <code>&lt;pre&gt;</code>. Горизонтальну лінію дає <code>&lt;hr&gt;</code>, а перенесення рядка — <code>&lt;br&gt;</code>, але для відступів між абзацами його не використовують."], "code": ["<p>Це <strong>дуже важливо</strong>, а це <em>з наголосом</em>.</p>\n<p>Виведіть текст командою <code>console.log()</code>.</p>\n\n<blockquote>\n  <p>Код пишеться один раз, а читається багато разів.</p>\n</blockquote>\n\n<pre><code>function hello() {\n  return \"Привіт\";\n}</code></pre>\n\n<hr>\n<p>H<sub>2</sub>O і 2<sup>3</sup></p>"], "note": "Теги <code>&lt;b&gt;</code> та <code>&lt;i&gt;</code> лише змінюють вигляд. Якщо текст справді важливий, беріть <code>&lt;strong&gt;</code> та <code>&lt;em&gt;</code>: їх розуміють і програми для незрячих.", "easy": "Теги тексту — це позначки на полях: «це важливо», «це цитата», «це код». Вигляд додають пізніше, через CSS.", "work": "У команді принцип такий: HTML відповідає за зміст і структуру, а CSS за вигляд. Тому не використовують теги лише для зовнішнього ефекту і не стилізують текст атрибутами.", "tasks": ["Оформіть абзац з важливим словом, цитатою та фрагментом коду.", "Зробіть формулу H2O із правильним нижнім індексом."]}, "media": {"t": "Зображення, аудіо та відео", "p": ["Зображення вставляє тег <code>&lt;img&gt;</code> з атрибутами <code>src</code> (шлях) та <code>alt</code> (опис для тих, хто не бачить картинку). Вказані <code>width</code> і <code>height</code> заздалегідь резервують місце, і сторінка не «стрибає» під час завантаження.", "Відео й аудіо додають тегами <code>&lt;video&gt;</code> та <code>&lt;audio&gt;</code> з атрибутом <code>controls</code>. Тег <code>&lt;picture&gt;</code> дозволяє віддавати різні файли для різних екранів."], "code": ["<img src=\"images/cat.jpg\" alt=\"Руда кішка спить на підвіконні\"\n     width=\"400\" height=\"300\" loading=\"lazy\">\n\n<video src=\"video/intro.mp4\" controls width=\"480\"></video>\n<audio src=\"audio/theme.mp3\" controls></audio>\n\n<picture>\n  <source srcset=\"images/hero.webp\" type=\"image/webp\">\n  <img src=\"images/hero.jpg\" alt=\"Команда за роботою\">\n</picture>"], "note": "Атрибут <code>loading=\"lazy\"</code> відкладає завантаження картинок, які ще не видно на екрані, і прискорює відкриття сторінки.", "easy": "Тег img — це вікно в стіні сторінки, а alt — табличка під ним для тих, хто крізь вікно нічого не бачить.", "work": "Великі зображення — головна причина повільних сайтів. Перед додаванням їх стискають і підбирають формат (WebP чи AVIF замість важкого PNG), а alt пишуть змістовно, а не «картинка».", "tasks": ["Вставте зображення з правильним alt і розмірами.", "Додайте відеоплеєр із кнопками керування."]}, "forms2": {"t": "Форми: типи полів і валідація", "p": ["Тег <code>&lt;input&gt;</code> має десятки типів: <code>text</code>, <code>email</code>, <code>password</code>, <code>number</code>, <code>date</code>, <code>checkbox</code>, <code>radio</code>, <code>file</code>. Для списків є <code>&lt;select&gt;</code>, для великого тексту — <code>&lt;textarea&gt;</code>.", "Браузер вміє перевіряти дані без JavaScript: атрибути <code>required</code>, <code>minlength</code>, <code>min</code>, <code>max</code>, <code>pattern</code>. Кожне поле повинно мати <code>&lt;label&gt;</code> і атрибут <code>name</code>, за яким дані потраплять на сервер."], "code": ["<form action=\"/register\" method=\"post\">\n  <label for=\"email\">Пошта</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required>\n\n  <label for=\"age\">Вік</label>\n  <input id=\"age\" name=\"age\" type=\"number\" min=\"14\" max=\"99\">\n\n  <label for=\"level\">Рівень</label>\n  <select id=\"level\" name=\"level\">\n    <option value=\"beginner\">Початковий</option>\n    <option value=\"middle\">Середній</option>\n  </select>\n\n  <label><input type=\"checkbox\" name=\"agree\" required> Погоджуюсь з умовами</label>\n  <button type=\"submit\">Зареєструватися</button>\n</form>"], "note": "Перевірка в браузері легко обходиться, тому сервер повторно перевіряє всі дані: на HTML-валідацію як на захист покладатися не можна.", "easy": "Форма — це паперова анкета: label — підпис біля клітинки, input — сама клітинка, а атрибути required та min — правила заповнення.", "work": "Форма реєстрації чи оплати — кожен день в роботі веброзробника. Зручність (правильні типи полів на мобільному, автозаповнення, зрозумілі помилки) прямо впливає на конверсію сайту.", "tasks": ["Зробіть форму зворотного зв'язку з іменем, поштою та повідомленням.", "Додайте перевірку, що вік не менший за 14."]}, "semantic": {"t": "Семантичні теги HTML5", "p": ["Раніше всю сторінку будували з однакових <code>&lt;div&gt;</code>. Семантичні теги описують роль блока: <code>&lt;header&gt;</code> (шапка), <code>&lt;nav&gt;</code> (навігація), <code>&lt;main&gt;</code> (головний вміст, один на сторінку), <code>&lt;section&gt;</code>, <code>&lt;article&gt;</code>, <code>&lt;aside&gt;</code>, <code>&lt;footer&gt;</code>.", "Такі теги допомагають пошуковим системам і програмам для незрячих розібратися в сторінці, а вам і колегам — швидше читати код."], "code": ["<body>\n  <header>\n    <a href=\"/\" class=\"logo\">Мій сайт</a>\n    <nav>\n      <a href=\"/about\">Про нас</a>\n      <a href=\"/blog\">Блог</a>\n    </nav>\n  </header>\n\n  <main>\n    <article>\n      <h1>Заголовок статті</h1>\n      <p>Текст статті…</p>\n    </article>\n    <aside>Реклама або схожі статті</aside>\n  </main>\n\n  <footer><p>&copy; 2026 Мій сайт</p></footer>\n</body>"], "note": "Тег <code>&lt;div&gt;</code> лишається потрібним, коли блок потрібен лише для оформлення і не має власного змісту.", "easy": "Семантичні теги — це таблички на дверях будівлі: «вхід», «каса», «склад». Усі одразу розуміють, що за чим.", "work": "Правильна семантична розмітка — одна з перших речей, які перевіряють на код-рев'ю та в тестових завданнях з верстки. Вона ж впливає на SEO.", "tasks": ["Перепишіть сторінку з самих div на семантичні теги.", "Знайдіть на будь-якому сайті в DevTools header, nav і main."]}, "a11y": {"t": "Доступність (a11y)", "p": ["Доступний сайт придатний для всіх: людей, що користуються зчитувачами екрана, клавіатурою замість миші або мають слабкий зір. Основа доступності — правильна семантика: заголовки за порядком, <code>alt</code> у зображень, <code>label</code> у полів.", "Коли стандартних тегів бракує, додають атрибути <code>aria-*</code>: наприклад <code>aria-label</code> для кнопки без тексту. Важливо, щоб усе працювало з клавіатури (Tab, Enter), а фокус був видимий."], "code": ["<button aria-label=\"Закрити вікно\">×</button>\n\n<nav aria-label=\"Основна навігація\">\n  <a href=\"/\" aria-current=\"page\">Головна</a>\n  <a href=\"/courses\">Курси</a>\n</nav>\n\n<img src=\"chart.png\" alt=\"Графік: продажі зросли на 20% за квартал\">\n<img src=\"decor.png\" alt=\"\">   <!-- декоративна картинка -->\n\n<a href=\"#main\" class=\"skip\">Перейти до змісту</a>"], "note": "Перше правило ARIA: якщо для задачі є стандартний HTML-тег (button, a, input), використовуйте його, а не <code>div</code> з атрибутами ARIA.", "easy": "Доступність — це пандус поряд зі сходами: він потрібен небагатьом щодня, але корисний майже кожному.", "work": "У великих компаніях і державних проєктах доступність — вимога закону або технічного завдання. Перевірити сайт швидко можна клавіатурою (Tab), а повний аудит зробить вбудований Lighthouse у DevTools.", "tasks": ["Пройдіть власною сторінкою лише клавішею Tab і перевірте, що фокус видно.", "Запустіть Lighthouse і подивіться оцінку Accessibility."]}, "meta": {"t": "Мета-теги, SEO та соцмережі", "p": ["У розділі <code>&lt;head&gt;</code> зберігається службова інформація. Тег <code>&lt;meta name=\"viewport\"&gt;</code> робить сторінку придатною для телефонів, <code>description</code> — це опис, який бачать у пошуку, а <code>&lt;title&gt;</code> задає назву вкладки та заголовок результату.", "Теги Open Graph (<code>og:title</code>, <code>og:image</code>) керують тим, як посилання виглядає під час публікації в соцмережах і месенджерах. Іконку сайту підключає <code>&lt;link rel=\"icon\"&gt;</code>."], "code": ["<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Iteris Code — вчимося кодити разом</title>\n  <meta name=\"description\" content=\"Безкоштовні уроки з програмування українською.\">\n  <link rel=\"icon\" href=\"/favicon.svg\">\n\n  <meta property=\"og:title\" content=\"Iteris Code\">\n  <meta property=\"og:description\" content=\"Безкоштовні уроки з програмування.\">\n  <meta property=\"og:image\" content=\"https://example.com/preview.png\">\n  <meta property=\"og:type\" content=\"website\">\n</head>"], "note": "Без тега viewport сторінка на телефоні відкриється зменшеною, ніби це десктопна версія.", "easy": "Мета-теги — це візитна картка сторінки: за нею пошукові системи й месенджери вирішують, як показати вашу сторінку.", "work": "Замовники часто просять «налаштувати SEO», і базові мета-теги з заголовком, описом та Open Graph — це перший крок. Кожна сторінка повинна мати власні title і description, а не однакові на весь сайт.", "tasks": ["Додайте до сторінки title, description та favicon.", "Підготуйте Open Graph-теги й перевірте їх, вставивши посилання в месенджер."]}, "project": {"t": "Структура проєкту, шляхи та підключення файлів", "p": ["Для сайту створюють папку, а в ній окремі підпапки для стилів, скриптів і зображень. Файли пов'язують шляхами. Відносний шлях відлічується від поточного файлу: <code>css/style.css</code>, а <code>../</code> піднімає на рівень вище. Абсолютний шлях починається з <code>/</code> і відлічується від кореня сайту.", "Стилі підключають у <code>head</code> тегом <code>&lt;link&gt;</code>, скрипти — тегом <code>&lt;script&gt;</code>. Атрибут <code>defer</code> вказує виконати скрипт після побудови сторінки."], "code": ["my-site/\n├── index.html\n├── about.html\n├── css/\n│   └── style.css\n├── js/\n│   └── main.js\n└── images/\n    └── logo.svg\n\n<!-- index.html -->\n<link rel=\"stylesheet\" href=\"css/style.css\">\n<script src=\"js/main.js\" defer></script>\n<img src=\"images/logo.svg\" alt=\"Логотип\">\n<a href=\"about.html\">Про нас</a>\n\n<!-- pages/team.html піднімається на рівень вище -->\n<link rel=\"stylesheet\" href=\"../css/style.css\">"], "note": "Назви файлів чутливі до регістру на більшості серверів: <code>Logo.svg</code> і <code>logo.svg</code> — різні файли, хоча на Windows це не помітно.", "easy": "Шлях до файлу — це адреса: відносний шлях говорить «від мене на два поверхи вниз», а абсолютний — «від центру міста».", "work": "Типова помилка початківця — «картинка не відображається» після публікації сайту: причиною бувають неправильний шлях або регістр літер. Перевіряйте вкладку Network у DevTools: червоні запити показують зламані шляхи.", "tasks": ["Створіть структуру папок сайту і підключіть стилі та скрипт.", "Додайте другу сторінку і зробіть посилання між ними."]}, "practice": {"t": "Практика: сторінка-портфоліо", "p": ["Зберемо повноцінну сторінку з усього, що ви вивчили: семантичні теги, навігація, список проєктів, форма й підвал. Стилів поки немає, тому сторінка виглядатиме просто, але її структура вже правильна. У курсі CSS ви оформите її.", "Спершу накидайте план на папері: які блоки, у якому порядку. Потім записуйте теги від зовнішніх до внутрішніх."], "code": ["<!DOCTYPE html>\n<html lang=\"uk\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Олена Коваль — веброзробниця</title>\n  <meta name=\"description\" content=\"Портфоліо веброзробниці: проєкти та контакти.\">\n</head>\n<body>\n  <header>\n    <h1>Олена Коваль</h1>\n    <nav aria-label=\"Основна навігація\">\n      <a href=\"#about\">Про мене</a>\n      <a href=\"#projects\">Проєкти</a>\n      <a href=\"#contact\">Контакти</a>\n    </nav>\n  </header>\n  <main>\n    <section id=\"about\">\n      <h2>Про мене</h2>\n      <p>Створюю <strong>швидкі та доступні</strong> сайти.</p>\n    </section>\n    <section id=\"projects\">\n      <h2>Проєкти</h2>\n      <article>\n        <h3>Сайт кав'ярні</h3>\n        <p>Адаптивний лендінг із меню та формою бронювання.</p>\n        <a href=\"https://example.com\">Дивитись</a>\n      </article>\n    </section>\n    <section id=\"contact\">\n      <h2>Контакти</h2>\n      <form action=\"#\" method=\"post\">\n        <label for=\"name\">Ім'я</label>\n        <input id=\"name\" name=\"name\" required>\n        <label for=\"msg\">Повідомлення</label>\n        <textarea id=\"msg\" name=\"msg\" required></textarea>\n        <button type=\"submit\">Надіслати</button>\n      </form>\n    </section>\n  </main>\n  <footer><p>&copy; 2026 Олена Коваль</p></footer>\n</body>\n</html>"], "note": "Перш ніж щось викладати, перевірте сторінку валідатором на validator.w3.org: він знаходить незакриті теги та інші помилки.", "easy": "Правильна верстка — це добре зроблений каркас будинку: оздоблення (CSS) можна міняти скільки завгодно, а каркас має бути надійним.", "work": "Портфоліо з живим посиланням — найкращий «документ» для початківця: його показують у резюме. Додайте його у репозиторій на GitHub і опублікуйте через GitHub Pages або Cloudflare Pages.", "tasks": ["Створіть власну сторінку-портфоліо за цим планом із вашими даними.", "Перевірте її валідатором і виправте помилки."]}};
  const easyOld = {"Структура HTML-документа": "Структура документа — це каркас будинку: фундамент (doctype), стіни (html), службові приміщення (head) і кімнати для людей (body).", "Заголовки, списки та посилання": "Заголовки — це розділи книги, списки — переліки, а посилання — двері на інші сторінки.", "Таблиці та форми": "Таблиця розкладає дані по рядках і стовпчиках, а форма збирає їх від користувача."};
  const workOld = {"Структура HTML-документа": "Кожна робоча сторінка починається з однакового шаблону: doctype, lang, charset і viewport. Тому розробники зберігають готовий шаблон у редакторі й вставляють його одним скороченням.", "Заголовки, списки та посилання": "Заголовки задають структуру для пошукових систем: h1 один на сторінку, далі h2, h3 по порядку. Меню сайту — це, по суті, список посилань, і його так і розмічають.", "Таблиці та форми": "Таблиці використовують лише для табличних даних, а не для розташування блоків на сторінці. Вигляд форм налаштовують CSS, а відправку — JavaScript і сервер."};
  const key = 'html';
  const byTitle = {};
  LESSONS[key].forEach(l => { byTitle[l.t] = l; l.easy = easyOld[l.t]; l.work = workOld[l.t]; });
  const T = t => { if (!byTitle[t]) throw new Error("Немає уроку: " + t); return byTitle[t]; };
  LESSONS[key] = [N.tools, T("Структура HTML-документа"), T("Заголовки, списки та посилання"), N.text, N.media, T("Таблиці та форми"), N.forms2, N.semantic, N.a11y, N.meta, N.project, N.practice];
  CHAPTERS[key] = [["Початок", 0], ["Вміст сторінки", 2], ["Структура й якість", 7], ["Практика", 10]];
  CHAPTERS[key].forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS[key].length;
    for (let j = from; j < to; j++) LESSONS[key][j].ch = name;
  });
})();

/* ===== CSS ===== */
(function () {
  const N = {"cascade": {"t": "Як працює CSS: каскад, специфічність і успадкування", "p": ["Каскад — це правила, за якими браузер вирішує, яке з кількох правил застосувати до елемента. Перемагає більш специфічний селектор: <code>#id</code> сильніший за <code>.class</code>, а той сильніший за тег. Якщо специфічність однакова, перемагає правило, що йде пізніше.", "Деякі властивості успадковуються від батьківського елемента (<code>color</code>, <code>font-family</code>), а інші, наприклад <code>border</code>, ні. Слово <code>!important</code> ламає порядок, тому ним майже не користуються."], "code": ["p { color: gray; }            /* найслабше: тег */\n.note { color: blue; }        /* клас сильніше */\n#main-note { color: green; }  /* id ще сильніше */\n\n/* <p id=\"main-note\" class=\"note\">Текст</p> стане зеленим */\n\nbody { font-family: Arial, sans-serif; color: #222; }\n/* усі нащадки body успадкують шрифт і колір */\n\n.button { color: white; }\n.button { color: yellow; }    /* однакова специфічність: перемагає останнє */"], "note": "Якщо стиль «не застосовується», відкрийте DevTools: у вкладці Styles закреслені правила показують, що їх перебито іншим.", "easy": "Каскад — це суперечка правил, у якій перемагає той, хто конкретніший. Наприклад, вказівка «усім учням» слабша за «учневі Іванові».", "work": "Більшість проблем із «стиль не працює» — це специфічність. Досвідчені розробники будують CSS так, щоб селектори були короткими й однаковими за силою, і майже ніколи не використовують <code>!important</code>.", "tasks": ["Створіть два правила для одного елемента і подивіться, яке спрацює.", "Знайдіть у DevTools закреслене правило на будь-якому сайті."]}, "pseudo": {"t": "Псевдокласи та псевдоелементи", "p": ["Псевдоклас описує стан елемента: <code>:hover</code> (курсор над ним), <code>:focus</code>, <code>:active</code>, <code>:first-child</code>, <code>:nth-child(2n)</code>, <code>:not(...)</code>. Також вони допомагають стилізувати перший чи парний елемент списку без додаткових класів.", "Псевдоелемент створює «віртуальний» елемент: <code>::before</code> та <code>::after</code> додають вміст до або після елемента, а <code>::placeholder</code> оформлює підказку в полі. Комбінатори: <code>a b</code> (нащадок), <code>a &gt; b</code> (прямий нащадок), <code>a + b</code> (сусід)."], "code": ["a { color: #2f5bea; }\na:hover { text-decoration: underline; }\nbutton:focus-visible { outline: 3px solid orange; }\n\nli:nth-child(even) { background: #f4f6ff; }\nli:first-child { font-weight: bold; }\n.card:not(.active) { opacity: .7; }\n\n.required::after { content: \" *\"; color: red; }\ninput::placeholder { color: #999; }\n\nnav > a + a { margin-left: 12px; }"], "note": "Не прибирайте обведення фокуса (<code>outline: none</code>) без заміни: людям, що працюють з клавіатури, воно потрібне.", "easy": "Псевдоклас — це «настрій» елемента: коли на нього навели курсор, натиснули чи сфокусували. Псевдоелемент — вигаданий допоміжний елемент.", "work": "Ефекти наведення, зебра в таблицях та позначки обов'язкових полів — повсякденні задачі. Вони зменшують кількість зайвих класів у HTML.", "tasks": ["Зробіть, щоб парні рядки таблиці були іншого кольору.", "Додайте зірочку до підписів обов'язкових полів через ::after."]}, "units": {"t": "Кольори, одиниці та шрифти", "p": ["Кольори задають назвою (<code>tomato</code>), шістнадцятковим кодом (<code>#2F5BEA</code>), через <code>rgb()</code> або <code>hsl()</code>. Прозорість додає четвертий параметр: <code>rgb(0 0 0 / 50%)</code>.", "Одиниці бувають абсолютні (<code>px</code>) та відносні: <code>rem</code> залежить від розміру шрифту сторінки, <code>em</code> — від батьківського елемента, <code>%</code> — від розміру батька, <code>vw</code>/<code>vh</code> — від розміру вікна. Для тексту краще <code>rem</code>."], "code": ["html { font-size: 100%; }          /* зазвичай 16px */\nbody {\n  font-family: \"Inter\", Arial, sans-serif;\n  font-size: 1rem;\n  line-height: 1.6;\n  color: #1c2437;\n  background-color: #f7f8fc;\n}\nh1 { font-size: 2.5rem; }\n.hero { height: 80vh; padding: 2rem; }\n.overlay { background: rgb(0 0 0 / 40%); }\n.accent { color: hsl(222 83% 56%); }"], "note": "Шрифти від Google Fonts підключають тегом <code>&lt;link&gt;</code> у head. Завжди вказуйте запасні шрифти: <code>Arial, sans-serif</code>.", "easy": "px — це точна міліметрівка, а rem — «гумова» лінійка, що підлаштовується під налаштування користувача.", "work": "Користувачі збільшують шрифт у браузері, тому розміри тексту й відступи зазвичай задають у rem. Кольори проєкту беруть із дизайн-макета й виносять у змінні.", "tasks": ["Задайте для сторінки шрифт, колір тексту й фону.", "Зробіть блок висотою 50% висоти екрана."]}, "textbg": {"t": "Текст, фони, рамки та тіні", "p": ["Для тексту є <code>font-weight</code>, <code>text-align</code>, <code>text-decoration</code>, <code>text-transform</code>, <code>letter-spacing</code>, <code>line-height</code>. Оптимальна висота рядка для читання — приблизно 1.5–1.7.", "Фон задає <code>background</code> (колір, градієнт, зображення). Рамку — <code>border</code>, заокруглення — <code>border-radius</code>, тінь — <code>box-shadow</code>."], "code": ["h1 {\n  text-align: center;\n  text-transform: uppercase;\n  letter-spacing: .04em;\n}\n.card {\n  background: #fff;\n  border: 1px solid #e3e7f3;\n  border-radius: 12px;\n  box-shadow: 0 4px 16px rgb(20 33 61 / 10%);\n}\n.hero {\n  background: linear-gradient(135deg, #2f5bea, #7b61ff);\n  color: #fff;\n}\n.avatar { width: 80px; height: 80px; border-radius: 50%; }"], "note": "Тінь і заокруглення роблять інтерфейс «сучасним», але не варто перебільшувати: слабка, розмита тінь виглядає охайніше.", "easy": "Ці властивості — косметика: шрифт, фарба, рамка й тінь. Вони перетворюють голу структуру на привабливий вигляд.", "work": "Дизайнер дає макет у Figma, а розробник переносить його в CSS: кольори, відступи, тіні. Точність цього переносу — те, що оцінюють у тестових завданнях з верстки.", "tasks": ["Зробіть картку із заокругленими кутами й м'якою тінню.", "Створіть блок із градієнтним фоном і білим текстом."]}, "position": {"t": "Display та position", "p": ["Властивість <code>display</code> визначає поведінку елемента: <code>block</code> займає весь рядок, <code>inline</code> лежить у тексті і не приймає ширину, <code>inline-block</code> поєднує обидва, а <code>none</code> ховає елемент.", "Властивість <code>position</code> керує розташуванням: <code>relative</code> зсуває від звичайного місця, <code>absolute</code> позиціонує відносно найближчого предка з position, <code>fixed</code> прилипає до вікна, <code>sticky</code> «приклеюється» під час прокрутки. Порядок накладання задає <code>z-index</code>."], "code": [".badge {\n  position: absolute;\n  top: -8px;\n  right: -8px;\n}\n.card { position: relative; }       /* точка відліку для .badge */\n\n.header {\n  position: sticky;\n  top: 0;\n  z-index: 10;\n  background: #fff;\n}\n.hidden { display: none; }\n.tag { display: inline-block; padding: 2px 8px; }"], "note": "Елемент із <code>position: absolute</code> шукає предка з position, і якщо такого немає, відлічує від усієї сторінки. Тому предку зазвичай ставлять <code>position: relative</code>.", "easy": "absolute — це наклейка, яку клеять у конкретне місце на сторінці. relative батька — це аркуш, на якому вона лежить.", "work": "Липка шапка, значок на іконці, випадне меню, модальне вікно — усе це position і z-index. Типова помилка — розмістити елемент «навмання» пікселями, а не пов'язати його з потрібним блоком.", "tasks": ["Зробіть липку шапку, що не зникає під час прокрутки.", "Додайте на картку значок «Новинка» у правому верхньому куті."]}, "grid": {"t": "CSS Grid: сітка", "p": ["Grid розташовує елементи у двох вимірах одночасно: рядки й стовпчики. Достатньо задати контейнеру <code>display: grid</code> та описати стовпчики через <code>grid-template-columns</code>. Одиниця <code>fr</code> означає частку вільного місця.", "Функція <code>repeat(auto-fit, minmax(240px, 1fr))</code> створює адаптивну сітку без медіа-запитів: скільки карток вміщується в рядок, стільки й буде. Flexbox зручний для одного ряду, а Grid — для всієї сітки."], "code": [".gallery {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 24px;\n}\n\n.layout {\n  display: grid;\n  grid-template-columns: 240px 1fr;\n  grid-template-areas:\n    \"header header\"\n    \"sidebar main\"\n    \"footer footer\";\n  gap: 16px;\n}\n.layout header { grid-area: header; }\n.layout aside  { grid-area: sidebar; }\n.layout main   { grid-area: main; }\n.layout footer { grid-area: footer; }"], "note": "Вкладені контейнери можна комбінувати: Grid для загальної сітки сторінки, а Flexbox для внутрішнього вмісту карток.", "easy": "Flexbox вишиковує людей у шеренгу, а Grid — розсаджує за місцями в залі кінотеатру.", "work": "Сітка карток, головна сторінка з бічною колонкою, дашборд — стандартні завдання. Вміння вибрати між Flexbox та Grid (один вимір чи два) — те, що перевіряють на співбесіді з верстки.", "tasks": ["Зробіть галерею з шести карток, яка сама перебудовується під ширину екрана.", "Створіть макет сторінки з шапкою, бічною колонкою, змістом і підвалом."]}, "responsive": {"t": "Адаптивний дизайн і медіа-запити", "p": ["Адаптивний сайт підлаштовується під екран телефона, планшета й комп'ютера. Основа — тег <code>&lt;meta name=\"viewport\"&gt;</code> та гнучкі одиниці. Підхід <b>mobile-first</b> передбачає, що спершу пишуть стилі для телефона, а для більших екранів додають через медіа-запити.", "Медіа-запит <code>@media (min-width: 768px)</code> застосовує правила лише від указаної ширини. Зображенням ставлять <code>max-width: 100%</code>, щоб вони не вилазили за контейнер."], "code": ["img { max-width: 100%; height: auto; }\n\n.container { padding: 16px; margin: 0 auto; max-width: 1100px; }\n.cards { display: grid; gap: 16px; grid-template-columns: 1fr; }\n\n@media (min-width: 640px) {\n  .cards { grid-template-columns: repeat(2, 1fr); }\n}\n@media (min-width: 1024px) {\n  .cards { grid-template-columns: repeat(3, 1fr); }\n  .container { padding: 32px; }\n}"], "note": "Стандартні точки перелому — приблизно 640, 768 і 1024 пікселі, але краще орієнтуватись на те, де ламається саме ваш макет.", "easy": "Адаптивність — це як вода: вона приймає форму посудини, будь то склянка (телефон) чи ванна (монітор).", "work": "Понад половина трафіку приходить з телефонів, тому адаптивна верстка — обов'язкова вимога. Перевіряйте сайт у режимі пристроїв у DevTools (Ctrl+Shift+M), а не лише розтягуючи вікно.", "tasks": ["Зробіть, щоб сітка карток була в 1, 2 або 3 стовпчики залежно від ширини.", "Перевірте сторінку в режимі мобільного пристрою в DevTools."]}, "vars": {"t": "Змінні CSS і темна тема", "p": ["Змінні CSS (кастомні властивості) зберігають значення, які повторюються: кольори, відступи, радіуси. Їх оголошують з двома дефісами в селекторі <code>:root</code> і використовують через <code>var(--назва)</code>. Змінивши змінну в одному місці, ви змінюєте її скрізь.", "Темну тему роблять, перевизначивши змінні в медіа-запиті <code>prefers-color-scheme: dark</code> або в атрибуті на елементі <code>html</code>."], "code": [":root {\n  --bg: #ffffff;\n  --text: #1c2437;\n  --accent: #2f5bea;\n  --radius: 12px;\n  --gap: 16px;\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --bg: #0b1020;\n    --text: #e8ecfa;\n  }\n}\n\nbody { background: var(--bg); color: var(--text); }\n.button {\n  background: var(--accent);\n  border-radius: var(--radius);\n  padding: calc(var(--gap) / 2) var(--gap);\n}"], "note": "Змінні мають каскад: їх можна перевизначити всередині окремого блока, наприклад, змінити колір акценту лише для однієї секції.", "easy": "Змінні — це палітра художника: змішав фарбу раз, а користуєшся в десяти місцях. Захотів інший колір, змінив у палітрі.", "work": "Дизайн-система будь-якого проєкту будується на змінних: кольори, шрифти, відступи. Уміння швидко змінити тему чи брендовий колір у одному місці — те, що цінують у командах.", "tasks": ["Винесіть усі кольори сторінки у змінні.", "Додайте темну тему через prefers-color-scheme."]}, "anim": {"t": "Переходи та анімації", "p": ["Перехід (<code>transition</code>) плавно змінює значення властивості, коли воно міняється, наприклад при наведенні курсору. Вказують властивість, тривалість і функцію пом'якшення. Анімації роблять для кращого відгуку, а не для краси: 150–300 мілісекунд.", "Складніші рухи описують через <code>@keyframes</code> та властивість <code>animation</code>. Найплавніше анімуються <code>transform</code> та <code>opacity</code>, бо вони не змушують браузер перераховувати розкладку."], "code": [".button {\n  background: #2f5bea;\n  transition: transform .2s ease, background-color .2s ease;\n}\n.button:hover {\n  background: #1f3fb8;\n  transform: translateY(-2px);\n}\n\n@keyframes pulse {\n  0%   { transform: scale(1); }\n  50%  { transform: scale(1.08); }\n  100% { transform: scale(1); }\n}\n.badge { animation: pulse 1.5s ease-in-out infinite; }\n\n@media (prefers-reduced-motion: reduce) {\n  * { animation: none !important; transition: none !important; }\n}"], "note": "Користувачі, яким рух шкодить, вмикають у системі зменшення анімацій. Відповідний медіа-запит <code>prefers-reduced-motion</code> варто враховувати.", "easy": "Перехід — це плавне «затемнення» замість раптового перемикання світла: елемент змінюється не миттєво, а за кілька десятих секунди.", "work": "Плавні ефекти для кнопок, карток і меню — стандарт сучасних сайтів. Але надмірні анімації сповільнюють сторінку, тому в команді слідкують, щоб рухалися лише transform та opacity.", "tasks": ["Зробіть кнопку, що злегка піднімається при наведенні.", "Створіть анімацію появи картки з прозорості 0 до 1."]}, "practice": {"t": "Практика: оформлюємо сторінку-портфоліо", "p": ["Оформимо сторінку з курсу HTML: шапка з навігацією, адаптивна сітка проєктів, акцентний колір через змінні та підтримка темної теми. Усе виконується лише CSS, без зміни структури HTML.", "Працюйте за порядком: спершу змінні та базові стилі, потім шапка, потім сітка, наприкінці адаптивність і дрібні ефекти."], "code": ["/* style.css */\n:root { --bg:#fff; --text:#1c2437; --accent:#2f5bea; --card:#f4f6ff; --radius:12px; }\n@media (prefers-color-scheme: dark) { :root { --bg:#0b1020; --text:#e8ecfa; --card:#141b33; } }\n\n* { box-sizing: border-box; }\nbody { margin: 0; font: 1rem/1.6 Arial, sans-serif; background: var(--bg); color: var(--text); }\nmain, header, footer { max-width: 1000px; margin: 0 auto; padding: 16px; }\n\nheader { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 12px; }\nnav { display: flex; gap: 16px; }\nnav a { color: var(--accent); text-decoration: none; }\nnav a:hover { text-decoration: underline; }\n\n#projects { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }\narticle { background: var(--card); padding: 16px; border-radius: var(--radius); transition: transform .2s; }\narticle:hover { transform: translateY(-3px); }\n\nbutton { background: var(--accent); color: #fff; border: 0; padding: 10px 18px; border-radius: var(--radius); cursor: pointer; }\ninput, textarea { width: 100%; padding: 8px; margin: 4px 0 12px; }"], "note": "Додайте <code>box-sizing: border-box</code> для всіх елементів: так ширина враховує відступи і рамки, і макет не «розповзається».", "easy": "Тепер ви збираєте все разом: HTML дав каркас, CSS додав вигляд, а змінні та адаптивність зробили сторінку гнучкою.", "work": "Верстка за макетом — типове тестове завдання. Закінчений, охайний, адаптивний сайт у вашому GitHub — кращий аргумент для роботодавця, ніж перелік вивчених тем.", "tasks": ["Оформіть своє портфоліо з HTML-курсу за цим прикладом.", "Додайте власний акцентний колір і переконайтеся, що сторінка гарно виглядає на телефоні."]}};
  const easyOld = {"Підключення CSS і селектори": "Селектор — це адреса: «усім абзацам», «усім елементам із класом card». Далі йде перелік того, що з ними зробити.", "Блочна модель": "Кожен елемент — коробка: вміст, внутрішній відступ, рамка й зовнішній відступ, як посилка в пакуванні.", "Flexbox: розташування елементів": "Flexbox вишиковує елементи у ряд або стовпчик і дозволяє розтягувати, вирівнювати й розподіляти вільне місце."};
  const workOld = {"Підключення CSS і селектори": "У проєктах дотримуються простих правил: стилі лежать в окремих файлах, селектори короткі, класи названі за змістом (<code>.card</code>, <code>.button</code>), а не за виглядом (<code>.red-text</code>).", "Блочна модель": "Саме через блочну модель з'являється більшість «чому все поїхало» на початку. Тому майже кожен проєкт починається з правила <code>box-sizing: border-box</code> для всіх елементів.", "Flexbox: розташування елементів": "Flexbox використовують у кожному меню, шапці, ряду кнопок та центруванні. Приклад «відцентруй блок по центру» — найчастіше питання на початкових співбесідах із верстки."};
  const key = 'css';
  const byTitle = {};
  LESSONS[key].forEach(l => { byTitle[l.t] = l; l.easy = easyOld[l.t]; l.work = workOld[l.t]; });
  const T = t => { if (!byTitle[t]) throw new Error("Немає уроку: " + t); return byTitle[t]; };
  LESSONS[key] = [N.cascade, T("Підключення CSS і селектори"), N.pseudo, N.units, T("Блочна модель"), N.textbg, N.position, T("Flexbox: розташування елементів"), N.grid, N.responsive, N.vars, N.anim, N.practice];
  CHAPTERS[key] = [["Початок", 0], ["Основи", 2], ["Макет", 6], ["Сучасний CSS", 9], ["Практика", 12]];
  CHAPTERS[key].forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS[key].length;
    for (let j = from; j < to; j++) LESSONS[key][j].ch = name;
  });
})();

/* ===== GIT: 10 уроків ===== */
(function () {
  const N = {"setup": {"t": "Встановлення Git і налаштування", "p": ["Завантажте Git із git-scm.com і встановіть із типовими параметрами. На Windows разом із ним з'явиться термінал Git Bash. Перевірте установку командою <code>git --version</code>. Також створіть безкоштовний обліковий запис на GitHub: це місце, де зберігають код і працюють у команді.", "Одноразово вкажіть своє ім'я та пошту: вони потраплять у кожен ваш коміт. Для безпечної роботи з GitHub створіть SSH-ключ і додайте його публічну частину в налаштуваннях облікового запису (Settings → SSH keys). Так не доведеться вводити пароль при кожному відправленні змін."], "code": ["git --version\n\ngit config --global user.name \"Ваше Ім'я\"\ngit config --global user.email \"you@example.com\"\ngit config --global init.defaultBranch main\ngit config --global core.editor \"code --wait\"\ngit config --list\n\n# SSH-ключ для GitHub\nssh-keygen -t ed25519 -C \"you@example.com\"\ncat ~/.ssh/id_ed25519.pub     # цей рядок вставте в налаштування GitHub\nssh -T git@github.com"], "note": "Приватний ключ (файл без <code>.pub</code>) нікому не передавайте й не завантажуйте в репозиторій. У GitHub додають лише публічний.", "easy": "Git — це журнал змін вашого коду з машиною часу, а GitHub — хмарна бібліотека, куди цей журнал можна відправити й показати колегам.", "work": "На першому ж робочому дні вам видадуть доступ до репозиторію компанії, і перше, що потрібно, — налаштований Git і SSH-ключ. Пошта в налаштуваннях має збігатись із поштою в GitHub, інакше коміти не прив'яжуться до вашого профілю.", "tasks": ["Встановіть Git і налаштуйте ім'я та пошту.", "Створіть SSH-ключ, додайте його в GitHub і перевірте з'єднання."]}, "undo": {"t": "Перегляд і скасування змін", "p": ["Перш ніж фіксувати зміни, дивіться, що саме змінилося: <code>git status</code> показує список файлів, а <code>git diff</code> — самі рядки. Файли, які не мають потрапляти в репозиторій (паролі, залежності, зібрані файли), перераховують у <code>.gitignore</code>.", "Скасувати можна по-різному. <code>git restore</code> відновлює файл до останнього коміту, <code>git restore --staged</code> прибирає файл з індексу, <code>git commit --amend</code> виправляє останній коміт, а <code>git revert</code> створює новий коміт, що скасовує старий, і тому безпечний для спільної історії."], "code": ["git status\ngit diff                       # зміни, ще не додані в індекс\ngit diff --staged              # зміни, додані в індекс\n\ngit restore index.html         # відкинути зміни у файлі\ngit restore --staged style.css # прибрати з індексу, зміни лишаються\n\ngit commit --amend -m \"Виправлене повідомлення\"\n\ngit revert a1b2c3d             # новий коміт, що скасовує a1b2c3d\n\n# .gitignore\nnode_modules/\n.env\ndist/\n*.log"], "note": "Команда <code>git reset --hard</code> безповоротно видаляє незафіксовані зміни. Перед її запуском переконайтесь, що вони вам справді не потрібні.", "easy": "restore — це «відмінити останні правки у файлі», amend — «переписати останній запис у журналі», а revert — «додати новий запис, що скасовує старий».", "work": "Помилки трапляються з усіма, і вміння їх безболісно виправити відрізняє впевненого розробника. Золоте правило: якщо коміт уже відправлено в спільну гілку, не переписуйте його, а скасовуйте через revert.", "tasks": ["Змініть файл, перегляньте diff і відкотіть зміни через restore.", "Зробіть коміт із помилкою в повідомленні й виправте його через amend."]}, "stash": {"t": "Stash, cherry-pick та rebase", "p": ["Іноді потрібно терміново перемкнутись на іншу гілку, а поточна робота ще не готова до коміту. <code>git stash</code> ховає незафіксовані зміни «у шухляду», а <code>git stash pop</code> повертає їх. Команда <code>git cherry-pick</code> переносить один конкретний коміт в іншу гілку.", "<code>git rebase</code> перебудовує вашу гілку поверх свіжої версії іншої гілки, і історія виглядає лінійною, без зайвих злиттів. Інтерактивний режим (<code>rebase -i</code>) дозволяє об'єднати кілька дрібних комітів в один і виправити їхні повідомлення."], "code": ["# терміновий перехід, робота ще не готова\ngit stash\ngit switch hotfix\n# ...виправили, закомітили...\ngit switch feature-login\ngit stash pop\n\n# перенести один коміт\ngit cherry-pick a1b2c3d\n\n# оновити свою гілку відносно main\ngit switch feature-login\ngit fetch origin\ngit rebase origin/main\n\n# об'єднати останні три коміти в один\ngit rebase -i HEAD~3"], "note": "Ніколи не робіть rebase гілок, які вже відправлені й використовуються іншими: це переписує історію й ламає чужу роботу.", "easy": "stash — це шухляда для незакінченої роботи, cherry-pick — копіювання однієї сторінки з чужого зошита, а rebase — переписування вашої частини історії так, ніби ви почали з найсвіжішого стану.", "work": "У командах просять перед pull request оновити гілку відносно main і зібрати дрібні коміти «fix typo» в один змістовний. Це робить історію читабельною та спрощує пошук помилок.", "tasks": ["Сховайте незакінчені зміни через stash і поверніть їх.", "Об'єднайте три маленькі коміти в один через rebase -i."]}, "flow": {"t": "Процеси в командах: гілки та повідомлення комітів", "p": ["У командах домовляються про схему роботи з гілками. Найпростіша: головна гілка <code>main</code> завжди робоча, нова функція чи виправлення створюються в окремій гілці (наприклад, <code>feature/login</code> або <code>fix/header-bug</code>), після ревʼю гілка зливається через pull request.", "Повідомлення комітів теж мають формат. Популярний стандарт — Conventional Commits: тип, двокрапка і короткий опис (<code>feat</code>, <code>fix</code>, <code>docs</code>, <code>refactor</code>, <code>test</code>, <code>chore</code>)."], "code": ["git switch -c feature/user-profile\ngit commit -m \"feat: add user profile page\"\ngit commit -m \"fix: correct avatar size on mobile\"\ngit commit -m \"docs: describe profile settings in README\"\ngit push -u origin feature/user-profile\n# далі відкриваємо Pull Request на GitHub\n\n# хороше повідомлення відповідає на питання «що зроблено і навіщо»\n# погано: \"зміни\", \"fix\", \"123\"\n# добре:  \"fix: prevent double submit on payment form\" "], "note": "Один коміт — одна логічна зміна. Не змішуйте виправлення помилки й форматування половини проєкту в одному коміті.", "easy": "Гілка feature — це чернетка, а pull request — прохання колег прочитати її перед тим, як вона потрапить у чистову версію.", "work": "На співбесіді з Git часто питають «як ви працюєте в команді»: розкажіть про окремі гілки, pull request, ревʼю й зрозумілі повідомлення. Це показує, що ви знаєте реальний процес.", "tasks": ["Створіть гілку за схемою feature/…, зробіть два коміти за Conventional Commits і відправте її.", "Перепишіть три погані повідомлення комітів у зрозумілому форматі."]}, "release": {"t": "Теги, релізи та GitHub Actions", "p": ["Тег — це постійна позначка на конкретному коміті, найчастіше для версії програми: <code>v1.0.0</code>. Версії зазвичай нумерують за схемою SemVer: мажорна.мінорна.виправлення. На GitHub із тега створюють реліз із описом змін.", "GitHub Actions автоматично запускає завдання після подій у репозиторії: тести, перевірку коду, збирання, публікацію. Налаштування описують у файлі YAML у папці <code>.github/workflows</code>."], "code": ["git tag v1.0.0\ngit tag -a v1.1.0 -m \"Додано профіль користувача\"\ngit push origin --tags\ngit tag\n\n# .github/workflows/ci.yml\nname: CI\non:\n  push:\n    branches: [main]\n  pull_request:\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n      - run: npm ci\n      - run: npm test"], "note": "Відступи в YAML значущі: використовуйте пробіли, не табуляцію, і стежте за вирівнюванням рядків.", "easy": "Тег — це закладка у книзі на версії, яку ви випустили. GitHub Actions — робот, що перевіряє ваш код щоразу, коли ви його оновлюєте.", "work": "У більшості компаній код перевіряється автоматично: pull request не можна злити, поки не пройшли тести. Прочитати та трохи поправити чужий файл workflow — типове завдання для початківця.", "tasks": ["Поставте тег v0.1.0 на свій репозиторій і відправте його.", "Додайте найпростіший workflow, що виводить «Hello» при кожному push."]}, "recover": {"t": "Пошук помилок та відновлення: log, blame, bisect, reflog", "p": ["Історію переглядають командою <code>git log</code> з зручними прапорцями. <code>git blame</code> показує, хто й коли змінив кожен рядок файлу. А <code>git bisect</code> двійковим пошуком швидко знаходить коміт, що вніс помилку: ви лише відповідаєте «добре» чи «погано».", "Якщо ви випадково видалили гілку чи зробили невдалий reset, допоможе <code>git reflog</code>. Він зберігає всі переміщення вказівника HEAD, і з нього можна відновити «втрачений» коміт."], "code": ["git log --oneline --graph --decorate\ngit log --author=\"Олена\" --since=\"2 weeks ago\"\ngit log -p -- src/app.js          # зміни конкретного файлу\ngit blame src/app.js\n\n# пошук коміту з помилкою\ngit bisect start\ngit bisect bad                    # поточна версія зламана\ngit bisect good v1.0.0            # ця версія працювала\n# Git переключає на проміжні коміти, ви тестуєте й відповідаєте:\ngit bisect good    # або   git bisect bad\ngit bisect reset\n\n# відновлення\ngit reflog\ngit switch -c rescue a1b2c3d"], "note": "Git майже ніколи не видаляє дані одразу: навіть «втрачені» коміти зазвичай живуть у reflog кілька тижнів.", "easy": "log — це журнал подій, blame — «хто це написав», bisect — гра в «гарячо-холодно» для пошуку зламаного коміту, а reflog — страховий запис усіх ваших кроків.", "work": "Коли в проєкті раптом щось зламалося, бісект швидко знаходить момент. Вміння відновити «пропалий» коміт через reflog рятує і нерви, і дедлайни.", "tasks": ["Знайдіть командою blame, хто останнім змінив певний рядок.", "Видаліть тестову гілку й відновіть її через reflog."]}};
  const easyOld = {"Що таке Git і перші коміти": "Коміт — це знімок вашого проєкту в певний момент. Git зберігає ланцюжок таких знімків, до яких можна повернутись будь-коли.", "Гілки та злиття": "Гілка — це паралельна лінія роботи: можна експериментувати, не ламаючи основну версію, а потім злити результат.", "Віддалений репозиторій: GitHub": "Віддалений репозиторій — це копія вашого проєкту на сервері: push відправляє туди зміни, а pull забирає чужі.", "Командна робота: pull request і конфлікти": "Pull request — це прохання «подивіться мої зміни й прийміть їх». Конфлікт — ситуація, коли двоє змінили той самий рядок і Git просить вас обрати правильний варіант."};
  const workOld = {"Що таке Git і перші коміти": "Без Git не працює жодна команда розробників. Дрібні й змістовні коміти потрібні, щоб історія була зрозумілою, а будь-яку зміну можна було знайти й скасувати.", "Гілки та злиття": "У реальних проєктах ніхто не працює безпосередньо в main. Для кожного завдання створюють окрему гілку, і це перше, чого очікують від новачка в команді.", "Віддалений репозиторій: GitHub": "Звичка перед початком роботи робити pull, а після завершення push — основа спільної роботи. GitHub також слугує вашим портфоліо, тож стежте за охайністю репозиторіїв.", "Командна робота: pull request і конфлікти": "Ревʼю коду — звичайна частина роботи. Конфлікти трапляються регулярно, і вміння спокійно їх розв'язати цінується більше, ніж страх перед ними."};
  const byTitle = {};
  LESSONS.git.forEach(l => { byTitle[l.t] = l; l.easy = easyOld[l.t]; l.work = workOld[l.t]; });
  const T = t => { if (!byTitle[t]) throw new Error("Немає уроку: " + t); return byTitle[t]; };
  LESSONS.git = [N.setup, T("Що таке Git і перші коміти"), N.undo, T("Гілки та злиття"), T("Віддалений репозиторій: GitHub"),
    T("Командна робота: pull request і конфлікти"), N.stash, N.flow, N.release, N.recover];
  CHAPTERS.git = [["Початок", 0], ["Щоденна робота", 2], ["GitHub і команда", 4], ["Просунуті прийоми", 6]];
  CHAPTERS.git.forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS.git.length;
    for (let j = from; j < to; j++) LESSONS.git[j].ch = name;
  });
})();

/* ===== BASH ===== */
(function () {
  const key = "bash";
  const N = {"find": {"t": "Пошук файлів і обробка тексту", "p": ["Команда <code>find</code> шукає файли за назвою, типом, розміром чи датою зміни. Для обробки тексту є невеликі утиліти, які поєднують конвеєром: <code>sort</code> сортує, <code>uniq</code> прибирає сусідні дублікати, <code>cut</code> вирізає стовпчики, <code>wc</code> рахує, <code>sed</code> замінює текст, <code>awk</code> обробляє таблиці.", "Із них складаються потужні однорядкові команди: наприклад, порахувати, скільки разів зустрівся кожен IP-адрес у лозі, одним рядком із кількох утиліт."], "code": ["find . -name \"*.log\"\nfind . -type f -size +10M\nfind . -name \"*.tmp\" -mtime +7 -delete\n\nsort names.txt | uniq -c | sort -rn | head -5\ncut -d',' -f2 students.csv\nsed 's/Python/Go/g' notes.txt\nawk -F',' '{ sum += $2 } END { print sum / NR }' students.csv\n\n# топ-5 адрес у лозі\ncut -d' ' -f1 access.log | sort | uniq -c | sort -rn | head -5"], "note": "Перед командою <code>find ... -delete</code> спершу запустіть її без <code>-delete</code>, щоб побачити, що саме буде видалено.", "easy": "Кожна утиліта — це простий інструмент: сортувальник, лічильник, ножиці. Конвеєр з'єднує їх у лінію, де кожна робить свій крок.", "work": "Розбір логів, швидка перевірка вмісту CSV, масова заміна в файлах — щоденні справи для адміністраторів і бекенд-розробників. Однорядкова команда часто економить години ручної роботи.", "tasks": ["Знайдіть усі файли .txt у папці та підпапках.", "Порахуйте, скільки унікальних значень у певному стовпчику CSV."]}, "env": {"t": "Змінні середовища та PATH", "p": ["Змінні середовища — це пари імен і значень, доступні всім програмам, що запускаються в терміналі. Їх виводить <code>printenv</code>, а значення читається через <code>$ІМ'Я</code>. Змінну для поточної сесії створюють командою <code>export</code>.", "Змінна <code>PATH</code> містить список папок, де система шукає виконувані файли. Тому команди <code>git</code> чи <code>python</code> запускаються з будь-якого місця. Постійні налаштування записують у файл <code>~/.bashrc</code>."], "code": ["echo $HOME\necho $PATH\nprintenv | head\n\nexport API_KEY=\"secret123\"\necho $API_KEY\n\nwhich python\nexport PATH=\"$PATH:$HOME/tools\"\n\n# постійно: додати у ~/.bashrc і перезавантажити\necho 'export EDITOR=nano' >> ~/.bashrc\nsource ~/.bashrc"], "note": "Секрети (ключі API, паролі) тримають у змінних середовища чи файлі <code>.env</code>, а не в коді, і не публікують у Git.", "easy": "PATH — це список полиць, на яких система шукає інструмент, коли ви вимовляєте його назву. Змінні середовища — записки, доступні всім програмам.", "work": "У будь-якому проєкті конфігурація (адреса бази, ключі) передається через змінні середовища. Помилка «command not found» зазвичай означає, що програми немає в PATH.", "tasks": ["Створіть змінну й виведіть її значення.", "Додайте свою папку зі скриптами до PATH."]}, "logic": {"t": "Умови, цикли та функції в скриптах", "p": ["Скрипти Bash підтримують гілки <code>if</code>, цикли <code>for</code> та <code>while</code>, а також функції. Умови пишуть у подвійних квадратних дужках: <code>[[ -f file ]]</code> (файл існує), <code>[[ $a -gt 5 ]]</code> (більше), <code>[[ $s == \"ok\" ]]</code> (рядки рівні).", "Скрипт отримує аргументи через <code>$1</code>, <code>$2</code>, а код завершення останньої команди зберігає <code>$?</code>: нуль означає успіх. Змінні в лапки беруть завжди: <code>\"$name\"</code>."], "code": ["#!/bin/bash\nset -e                       # зупинитись при першій помилці\n\ngreet() {\n  echo \"Привіт, $1!\"\n}\n\nif [[ $# -lt 1 ]]; then\n  echo \"Використання: $0 <ім'я>\"\n  exit 1\nfi\ngreet \"$1\"\n\nfor file in *.txt; do\n  if [[ -s \"$file\" ]]; then\n    echo \"$file не порожній\"\n  fi\ndone\n\ncount=1\nwhile [[ $count -le 3 ]]; do\n  echo \"Крок $count\"\n  ((count++))\ndone"], "note": "Забули лапки навколо змінної з пробілом у значенні — і Bash розіб'є її на кілька слів. Завжди пишіть <code>\"$var\"</code>.", "easy": "Скрипт — це рецепт для терміналу: ті самі команди, що ви вводили руками, зібрані в файл із розвилками й повторами.", "work": "Автоматизація — серце роботи DevOps: бекапи, розгортання, перевірка сервера. Початківцю дають змінити або розширити існуючий скрипт, тож треба вміти його прочитати.", "tasks": ["Напишіть скрипт, що приймає ім'я файлу й повідомляє, чи він існує.", "Створіть функцію, що виводить поточну дату й повідомлення."]}, "proc": {"t": "Процеси, сигнали та cron", "p": ["Кожна запущена програма — це процес. Список процесів показує <code>ps aux</code> та інтерактивний <code>top</code>. Команду можна запустити у фоні знаком <code>&amp;</code>, а зупинити за ідентифікатором командою <code>kill</code>. Сигнал <code>SIGTERM</code> просить завершитись, а <code>kill -9</code> примусово убиває процес.", "Для запуску за розкладом використовують <code>cron</code>. Розклад задають п'ятьма полями: хвилина, година, день місяця, місяць, день тижня."], "code": ["ps aux | grep python\ntop\nsleep 300 &                 # у фоні\njobs\nkill 12345                  # м'яко\nkill -9 12345               # примусово\n\n# crontab -e: щодня о 03:00 запускати резервну копію\n0 3 * * * /home/user/backup.sh >> /home/user/backup.log 2>&1\n# кожні 15 хвилин\n*/15 * * * * /home/user/check.sh"], "note": "Спершу використовуйте звичайний <code>kill</code> і лише якщо процес не реагує — <code>kill -9</code>: примусове завершення не дає програмі зберегти дані.", "easy": "Процес — це запущена програма, як працівник на заводі. kill — наказ йому піти, а cron — будильник, що запускає потрібну роботу за розкладом.", "work": "Зависла програма, зайнятий порт, завдання за розкладом на сервері — типові задачі. Умієте знайти процес і зупинити його — ви вже вирішили половину інцидентів.", "tasks": ["Запустіть команду у фоні й завершіть її через kill.", "Складіть запис cron для запуску скрипта щопонеділка о 9:00."]}, "net": {"t": "Мережа та SSH", "p": ["Для роботи з мережею в терміналі є <code>curl</code> (виконує запити й показує відповідь), <code>wget</code> (завантажує файли), <code>ping</code> (перевіряє доступність). Служба <code>ssh</code> дозволяє безпечно під'єднатися до віддаленого сервера й працювати в його терміналі.", "Копіювати файли на сервер і з нього можна через <code>scp</code>, а для постійного доступу без пароля використовують пару SSH-ключів."], "code": ["curl https://api.github.com/users/octocat\ncurl -s https://api.github.com/users/octocat | head -5\ncurl -X POST -H \"Content-Type: application/json\" \\\n     -d '{\"title\":\"Привіт\"}' https://jsonplaceholder.typicode.com/posts\nwget https://example.com/file.zip\nping -c 3 google.com\n\nssh user@192.168.1.10\nscp report.pdf user@192.168.1.10:/home/user/\nscp user@192.168.1.10:/var/log/app.log ."], "note": "Права на файл приватного ключа мають бути суворими: <code>chmod 600 ~/.ssh/id_ed25519</code>, інакше SSH відмовиться ним користуватись.", "easy": "curl — це браузер без вікна: він просить сторінку чи дані в сервера й виводить відповідь у термінал. ssh — захищений тунель до чужого комп'ютера.", "work": "Розробники роблять тестові запити до API через curl, підключаються по SSH до серверів і завантажують логи. Ці команди ви побачите в кожній інструкції з розгортання.", "tasks": ["Отримайте через curl дані з будь-якого відкритого API.", "Завантажте файл за допомогою wget і перевірте його."]}};
  const easyOld = {"Командний рядок: файли та папки": "Термінал — це текстове керування комп'ютером: замість мишки ви пишете команди, і система виконує їх.", "Перегляд тексту, пошук і конвеєри": "Конвеєр — це лінія на фабриці: вихід однієї команди одразу йде на вхід наступної.", "Права доступу та перші скрипти": "Права доступу — це ключі від кімнат: хто може читати, змінювати чи запускати файл. Скрипт — рецепт із команд."};
  const workOld = {"Командний рядок: файли та папки": "Більшість серверів не мають графічного інтерфейсу, тож уся робота з ними відбувається в терміналі. Швидка навігація й файлові команди — основа роботи розробника.", "Перегляд тексту, пошук і конвеєри": "grep і конвеєри використовують для пошуку помилок у логах — це перше, що роблять, коли на сервері щось пішло не так.", "Права доступу та перші скрипти": "Помилка «Permission denied» траплялась кожному. Розуміння прав і вміння написати простий скрипт — стандартні вимоги до початківця в DevOps та бекенді."};
  const byTitle = {};
  LESSONS[key].forEach(l => { byTitle[l.t] = l; l.easy = easyOld[l.t]; l.work = workOld[l.t]; });
  const T = t => { if (!byTitle[t]) throw new Error("Немає уроку: " + t); return byTitle[t]; };
  LESSONS[key] = [T("Командний рядок: файли та папки"), T("Перегляд тексту, пошук і конвеєри"), N.find, N.env, T("Права доступу та перші скрипти"), N.logic, N.proc, N.net];
  CHAPTERS[key] = [["Файли й текст", 0], ["Середовище та скрипти", 3], ["Система й мережа", 6]];
  CHAPTERS[key].forEach(([name, from], i, a) => {
    const to = i + 1 < a.length ? a[i + 1][1] : LESSONS[key].length;
    for (let j = from; j < to; j++) LESSONS[key][j].ch = name;
  });
})();
